\section{Proof of Main Results}\label{section:proof}

\subsection{Proof of Theorem~\ref{theorem:main}}


The following lemmas are needed in the proof of Theorem~\ref{theorem:main}.
Lemma~\ref{lemma:chi2_error} converts the $\chi^2$-distance of the proposal distributions $q^*$ and $q_{\btheta}$ into those of $p_i^*$ and $p_{\btheta, i}$:
\begin{lemma}\label{lemma:chi2_error}
We have
\begin{align*}
\log\{1+\chi^2(q^*(\xb_{\cB}|\yb)\|q_{\btheta}(\xb_{\cB}|\yb))\}\le\sum_{i\in\cB}\chi^2(p_i^*\|p_{\btheta, i}).
\end{align*}
\end{lemma}
Lemma~\ref{lemma:squared_error} characterizes the squared error of $h_B^*$ and $h_{\btheta, B}$:
\begin{lemma}\label{lemma:squared_error}
We have
\begin{align*}
&\EE_{\xb_{\cB}\sim p^*(\cdot|\yb)}|h_{\btheta, B}(\xb_{\cB}, \yb)-h_B^*(\xb_{\cB}, \yb)|^2\\
&\le\min\bigg\{4B^2, \sum_{k=2}^{n_t}\frac{2}{\binom{n_t-1}{k-1}}\sum_{\tilde\cB\subset\cB, |\tilde\cB|=k-1}\sum_{i\in\cB\backslash\tilde\cB}\epsilon_{i, \tilde\cB}(\yb)^2+2n_t\sum_{i\in\cB}\epsilon_i(\yb)^2\bigg\}.
\end{align*}
\end{lemma}
We also need several technical lemmas in~\citet{chen2026high}, which are listed in Appendix~\ref{section:auxiliary}. We now provide the proof of Theorem~\ref{theorem:main}.
\begin{proof}[Proof of Theorem~\ref{theorem:main}]
