\section{Introduction}

Let $G=(V,E)$ be a finite connected undirected graph, with positive edge conductances $(c_e)_{e\in E}$ and a distinguished root $r\in V$.
A weighted spanning tree $T$ has distribution
\begin{equation}\label{eq:tree-law}
 \PP(T=t)=Z_G^{-1}w(t),\qquad
 w(t)=\prod_{e\in t}c_e,\qquad Z_G=\sum_{t\text{ spanning tree}}w(t).
\end{equation}
Write $\gamma_x=[x,r]_T$ for its root path, including both endpoints, and $\LCA_T(x,y)$ for the lowest common ancestor
of $x$ and $y$, namely the first common vertex of $\gamma_x$
and $\gamma_y$ when followed towards $r$.
For $B\subseteq V\setminus\{r\}$, define
\begin{equation}\label{eq:h-a}
 H_B(x)=\PP(\gamma_x\cap B\ne\varnothing),\qquad
 a_B(x,y)=\PP(\LCA_T(x,y)\in B).
\end{equation}
Let $U_B=V\setminus(B\cup\{r\})$.
For distinct $x,y\in U_B$, let $J_B(x,y)$ be the probability that $x,y,r$ belong to three different components of the induced forest $T\setminus B$, and put $J_B(x,x)=0$.
We also write \(H_B=(H_B(x))_{x\in U_B}\) and \(J_B=(J_B(x,y))_{x,y\in U_B}\).

We establish the following inequality for weighted spanning trees.
\begin{theorem}[Quadratic ancestor inequality]\label{thm:separation}
For every $G,r,B$ as above, the matrix
$H_BH_B^{\mathsf T}-J_B$ is positive semidefinite. Consequently,
\begin{equation}\label{eq:ancestor}
 \sum_{x,y\in V}f(x)f(y)a_B(x,y)
 \le \left(\sum_{x\in V}f(x)H_B(x)\right)^2
\end{equation}
for every nonnegative $f:V\to\RR$.
For all $x,y\in V$, one also has
\begin{equation}\label{eq:pointwise}
 a_B(x,y)\le 2H_B(x)H_B(y).
\end{equation}
In particular, if $f$ is a probability distribution on $V$ and
$X,Y$ are independent with common law $f$,
independently of $T$, then \eqref{eq:ancestor} becomes
$\PP(\LCA_T(X,Y)\in B)
\le\PP(\gamma_X\cap B\ne\varnothing)^2$.
\end{theorem}

We prove Theorem~\ref{thm:separation} using completely log-concave matroid polynomials from Anari--Liu--Oveis Gharan--Vinzant~\cite{ALOV} and Br\"and\'en--Huh~\cite{BH}. We also refer to e.g.~\cite{COSW,BBL,Lyons} for related work on generating polynomials of spanning trees
and their negative dependence properties.
The constant $1$ in the inequality \eqref{eq:ancestor} is optimal.
Indeed, take the deterministic tree with edges $\{r,b\}$ and $\{b,x_i\}$, $1\le i\le k$, put $B=\{b\}$, and let $f$ be uniform on the $k$ leaves. The two sides of \eqref{eq:ancestor} are then $1-1/k$ and $1$, respectively.

Theorem~\ref{thm:separation} has the following two main applications. We call a graph \emph{transitive} if its conductance-preserving automorphisms act transitively on its vertices.

\begin{theorem}\label{thm:bk}
Let $G$ be a finite connected transitive weighted graph with $n$ vertices.
Let $T$ have law \eqref{eq:tree-law}, and let $X,Y$ be independent uniform vertices, independent of $T$.
Write $\gamma=[X,Y]_T$.
For every deterministic $B\subseteq V$,
\begin{equation}\label{eq:set-hit}
 \PP(\gamma\cap B\ne\varnothing)\ge\sqrt{\frac{|B|}{n}}.
\end{equation}
For a deterministic partition $\mathcal P=\{B_1,\ldots,B_k\}$ of $V$ into nonempty sets,
let $N_{\mathcal P}$ count the blocks of $\mathcal P$ visited by $\gamma$. Then
\begin{equation}\label{eq:partition-hit}
 \EE N_{\mathcal P}\ge\sum_{i=1}^k\sqrt{\frac{|B_i|}{n}}.
\end{equation}
In particular, let $d_T(X,Y)$ be the number of edges
in the unique path from $X$ to $Y$ in $T$. Then
\begin{equation}\label{eq:bk}
 \EE d_T(X,Y)\ge\sqrt n-1.
\end{equation}
\end{theorem}

Benjamini and Kozma~\cite[Introduction]{BK} asked whether the expected
UST distance between two independent uniform vertices of every finite transitive graph admits a universal lower bound of order $\sqrt n$. Theorem~\ref{thm:bk} then answers this question.
Previously, lower bounds of order $\sqrt n$ were 
obtained under high-dimensional or
model-specific assumptions~\cite{PR,Sch4}. See also~\cite{CHL,MNS,ANSdense,ANSghp,AS} for related results on UST
distances, diameters, and scaling limits.

Our second application is to the growth exponent
of three-dimensional LERW. Let $S$ be a simple random walk on $\ZZ^3$, started at $0$.
For $B_R:=\{x\in\ZZ^3:|x|<R\}$, set
\begin{equation}\label{eq:beta-def}
 \tau_R=\inf\{j\ge0:S_j\notin B_R\},\qquad
 M_R=|\LE(S[0,\tau_R])|,\qquad
 \beta=\lim_{R\to\infty}\frac{\log\EE M_R}{\log R}.
\end{equation}
The existence of the limit was proved by Shiraishi~\cite{ShiG}.
Let $\eta=\LE(S[0,\infty))$.

\begin{theorem}\label{thm:3d}
There is $c>0$ such that, for every $R\ge1$,
\begin{equation}\label{eq:occupation-main}
 \EE|\eta\cap B_R|\ge cR^{3/2}.
\end{equation}
Consequently, we have $\beta\ge3/2$.
\end{theorem}

Note that $\beta$ also equals the Hausdorff dimension of the scaling limit of the three-dimensional LERW~\cite{ShiH}.
The classical bound $\beta>1$ follows by comparison with random-walk
intersection exponents; see Lawler~\cite[Introduction]{Lawler1999} and the
references therein.
Recently, \cite{Liu} made this approach quantitative and improved it to $\beta>1.0001$. Theorem~\ref{thm:3d} also implies that two independent infinite LERWs on $\ZZ^3$ intersect infinitely often
a.s.; see Theorem~\ref{thm:independent-lerw}.

