\begin{thm}[\textbf{Ward identity}]\label{thm_intro_WARD_CILT}
Let $\Sigma$ be a compact Riemann surface with real-analytic boundary parametrizations $\zetabf=(\zeta_1,\ldots,\zeta_\b)$. Suppose $\b=\b^++\b^-$ where $\zeta_j$ is outgoing for $j=1,\ldots,\b^+$ and incoming for $j=\b^++1,\ldots,\b$. Let $\zbf=(z_1,\ldots,z_\s)$ be distinct marked points on $\Sigma^\circ$, $\vbf=(v_1,\ldots,v_\s)$ with $v_j\in T_{z_j}\Sigma\setminus\{0\}$ for each $j$, $\alphabf=(\alpha_1,\ldots,\alpha_\s)\in\Rb^\s$ electric charges such that $\alpha_j>Q$, $\alpha_jR\in\Zb$ for all $j$, and $\mbf=(m_1,\ldots,m_\s)\in\Zb^\s$ magnetic charges. Let $g$ be an admissible metric on $\Sigma$. We have the amplitude operator $\Ac_{\Sigma,g,\vbf,\alphabf,\mbf,\zetabf}:\Hc^{\otimes\b^-}\to\Hc^{\otimes\b^+}$. Finally, let ${\rm w}$ be a holomorphic vector field on $\Sigma$ (analytic up to the boundary). For each $j=1,\ldots,\b$, let ${\rm w}_j:=\zeta_j^*{\rm w}=-\sum_{n\in\Zb}w_{jn}z^{n+1}\pa_z$, where we extend $\zeta_j$ analytically so that ${\rm w}_j$ is holomorphic on an open neighborhood of $\Tb$. Then the following identity holds:
\begin{align*}
0 &= \sum_{j=1}^{\b^+}\Hbf_{{\rm w}_j}^{(j)}\Ac_{\Sigma,g,\vbf,\alphabf,\mbf,\zetabf} - \sum_{j=1}^{\b^-}\Ac_{\Sigma,g,\vbf,\alphabf,\mbf,\zetabf}\Hbf_{{\rm w}_{\b^++j}}^{(j)}
+ \sum_{j=1}^{\s}\left(\Delta_{\alpha_j,m_j}(\div_gW)(z_j)+W_\vbf^{(j)}\right)\Ac_{\Sigma,g,\vbf,\alphabf,\mbf,\zetabf} \\
&\qquad+ c_\L\left(-\sum_{j=1}^{\b^+}\frac{\Re w_{j0}}{12}+\sum_{j=\b^++1}^{\b}\frac{\Re w_{j0}}{12}-\frac{1}{96\pi}\int_\Sigma 2K_g\div_gW\,\d v_g\right)\Ac_{\Sigma,g,\vbf,\alphabf,\mbf,\zetabf},
\end{align*}
where $\Hbf_{{\rm w}}^{(j)}:=\id_\Hc \otimes \cdots \otimes \underset{j}{\underbrace{\Hbf_{\rm w}}} \otimes \cdots \otimes \id_\Hc$ acts on the $j$-th $\Hc$, $W={\rm w}+\bar{{\rm w}}$, and $W_\vbf^{(j)}$ denotes differentiation with respect to $v_j$ in the direction of $W$ at $z_j$. Here $\Hbf_{\rm w}$ is defined as in \eqref{intro_H_v}, summing over $n\in\Zb$.
\end{thm}

This is proved as \cref{ward_cilt}.

\begin{remark}
The dependence of $\Ac_{\Sigma,g,\vbf,\alphabf,\mbf,\zetabf}$ on $\vbf$ records the spin $R(\alpha_j-Q)m_j$ at each $z_j$. More precisely, if for $\thetabf=(\theta_1,\ldots,\theta_\s)\in\Rb^\s$ we write $e^{\i\thetabf}\vbf=(e^{\i\theta_1}v_1,\ldots,e^{\i\theta_\s}v_\s)$, then we have (\cite[Theorem 1.2(3)]{BCILT})
\begin{equation*}
    \Ac_{\Sigma,g,e^{\i\thetabf}\boldsymbol{\v},\alphabf,\mbf,\zetabf}=e^{\i R\sum_{j=1}^\s(\alpha_j-Q)m_j\theta_j}\Ac_{\Sigma,g,\vbf,\alphabf,\mbf,\zetabf}.
\end{equation*}
In the Ward identity above, the tangent vectors $\vbf$ are also deformed by the flow $f_t$ generated by $\mathrm{w}$. If each $(f_t)_*v_j=e^{\lambda_j(t)}P_{g,j,t}v_j$ where $P_{g,j,t}:T_{z_j}\Sigma\to T_{f_t(z_j)}\Sigma$ is the $g$-parallel transport along $t\mapsto f_t(z_j)$ and $\lambda_j(t)\in\Cb$ depends continuously on $t$, then writing $\theta_j:=\Im\lambda_j$, we have $\partial_t|_{t=0} \theta_j(t)=-\frac12\div_g(JW)(z_j)$, where $JW:=\i \mathrm{w}-\i\bar{\mathrm{w}}$. Thus
\begin{equation*}
    W_\vbf^{(j)}\Ac_{\Sigma,g,\vbf,\alphabf,\mbf,\zetabf}=-\frac\i2 R(\alpha_j-Q)m_j (\div_g(J W))(z_j)\Ac_{\Sigma,g,\vbf,\alphabf,\mbf,\zetabf}+W_\zbf^{(j)}\Ac_{\Sigma,g,\vbf,\alphabf,\mbf,\zetabf},
\end{equation*}
where $W_\zbf^{(j)}$ denotes differentiation with respect to the marked point $z_j$ while parallel transporting $v_j$.
\end{remark}

Finally, we also develop the analogous theory for BCILT, i.e., the case with (Neumann) boundary. In particular, we study the quantization of Segal's semigroup of semiannuli and use this to prove the Ward identities for general BCILT amplitudes. The results are summarized in \cref{sec_BCILT}; see \cref{thm_BCILT_semigroup,ward_bcilt} for the statements.

\subsection*{Organization of the paper}
In \cref{Sec_background}, we introduce the background notations and recall some definitions and facts that are used in the paper. \cref{Sec_segal_quant} defines the quantization of Segal's semigroup and establishes its relation with the amplitudes of annuli. \cref{sec_Virasoro} then studies the generators of this quantization and proves the Feynman--Kac formula; this is done first for the free field, then for the Liouville case. \cref{sec_con_diff} is devoted to proving the differentiability of amplitudes, which is applied in \cref{sec:ward} to prove the Ward identities. Finally, we give a rapid treatment of the analogous theory for BCILT in \cref{sec_BCILT}.

