\section{Preliminaries}
\label{sec:prelim}
\subsection{Triangulated categories}
\label{sec:prelim_triangulated}
\subsubsection{Terminology}
\label{sec:prelim_terminology}

We fix some terminology. 
See \cite[\S 1]{Neeman:2001}.
Let $\mathcal{T}$ be a triangulated category.
Note that $\operatorname{Hom}(X,Y)$ is an abelian group.
Given a morphism $u$, write $-u$ for its additive inverse.
Consider a distinguished triangle
\begin{equation}
    \label{eq:triangle}
    X\xrightarrow{u} Y\xrightarrow{v} Z\xrightarrow{w} X[1].
\end{equation}
Then TR2 asserts that
\begin{displaymath}
    \begin{aligned}
        Y
        & \xrightarrow{v} Z\xrightarrow{w} X[1]\xrightarrow{-u[1]} Y[1],
        \\& Z[-1]\xrightarrow{-w[-1]} X\xrightarrow{u} Y\xrightarrow{v} Z
    \end{aligned}
\end{displaymath}
are also distinguished.
Passing from \eqref{eq:triangle} to the first (resp.\ second) of these is called \textbf{rotating} (resp.\ \textbf{rotating backwards}).
Observe that negating two of the three morphisms of a distinguished triangle gives a distinguished triangle. 
Indeed, $(1_X,-1_Y,1_Z)$ is an isomorphism of triangles from $(u,v,w)$ to $(-u,-v,w)$.
For every $n\in \mathbb{Z}$, there exists a distinguished triangle
\begin{displaymath}
    X[n]\xrightarrow{u[n]} Y[n]\xrightarrow{v[n]} Z[n]\xrightarrow{(-1)^n w[n]} X[n+1].
\end{displaymath}
We call this \textbf{shifting} the given distinguished triangle by $[n]$.
By TR1, every $f\colon X\to Y$ can be completed into a distinguished triangle 
\begin{displaymath}
    X\xrightarrow{f} Y\to C_f\to X[1].
\end{displaymath}
We call $C_f$ a \textbf{cone} of $f$.
Rotating backwards gives
\begin{displaymath}
    F_f\to X\xrightarrow{f} Y\to F_f[1].
\end{displaymath}
We call $F_f := C_f[-1]$ a \textbf{cocone} of $f$.
Both are unique up to (non-unique) isomorphism.
By combining TR1 and TR2, it follows that every morphism can be realized as the first, second, or third of some distinguished triangle.
Moreover, given a morphism of distinguished triangles, if two of the three vertical morphisms are isomorphisms, then so is the third.
Indeed, this can be shown by rotating and applying \cite[Proposition 1.1.20]{Neeman:2001}.
\subsubsection{Generation}
\label{sec:prelim_generation}

Let $\mathcal{T}$ be a triangulated category admitting small coproducts and $\mathcal{S},\mathcal{S}^\prime$ full subcategories.
Write $\mathcal{S} \star \mathcal{S}^\prime$ for the full subcategory of objects $X$ admitting a distinguished triangle $S\to X\to S^\prime \to S[1]$ with $S\in \mathcal{S}$ and $S^\prime \in \mathcal{S}^\prime$.
Write $\operatorname{Coprod}(\mathcal{S})$ for the smallest strictly full subcategory containing $\mathcal{S}$ that is closed under small coproducts and extensions, and $\operatorname{smd}(\mathcal{S})$ for the full subcategory of direct summands of objects of $\mathcal{S}$.
For $H\in \mathcal{T}$ and integers $a\leq b$ put
\begin{displaymath}
    H[a,b] := \{ H[-k] : a\leq k\leq b \},
    \qquad 
    \overline{\langle H\rangle}^{[a,b]} := \operatorname{smd}(\operatorname{Coprod}(H[a,b])).
\end{displaymath}

The subcategory of compact objects is denoted by $\mathcal{T}^c$, consisting of those $c \in \mathcal{T}$ for which $\operatorname{Hom}(c,-)$ preserves coproducts.
These form a triangulated subcategory of $\mathcal{T}$. 
The \textbf{localizing subcategory} generated by a collection $\mathcal{S}\subseteq \mathcal{T}$, denoted by $\overline{\langle \mathcal{S} \rangle}^{(-\infty,\infty)}$, is the smallest triangulated subcategory containing $\mathcal{S}$ and closed under small coproducts.
If $\mathcal{T}^c$ is essentially small, then we say that $\mathcal{T}$ is \textbf{compactly generated} when $\mathcal{T} = \overline{\langle \mathcal{T}^c \rangle}^{(-\infty,\infty)}$.
Equivalently, $\mathcal{T}$ is compactly generated if, for any $E \in \mathcal{T}$ satisfying $\operatorname{Hom}(P, E) = 0$ for all $P \in \mathcal{T}^c$, one has $E \cong 0$.
An object $G\in \mathcal{T}^c$ is a \textbf{compact generator} of $\mathcal{T}$ if every $E\in \mathcal{T}$ with $\operatorname{Hom}(G[n],E)=0$ for all $n\in \mathbb{Z}$ satisfies $E\cong 0$.
An object of $\mathcal{T}^c$ is a \textbf{classical generator} of $\mathcal{T}^c$ if the smallest thick subcategory of $\mathcal{T}^c$ containing it is $\mathcal{T}^c$.
If $\mathcal{T}$ is compactly generated, then classical generators for $\mathcal{T}^c$ coincide with compact generators for $\mathcal{T}$ \cite[\href{https://stacks.math.columbia.edu/tag/09SR}{Tag 09SR}]{StacksProject}.
We say that $\mathcal{T}$ is \textbf{singly compactly generated} if it admits a compact generator. 
\subsubsection{\texorpdfstring{$t$}{t}-structures}
\label{sec:prelim_t-structures_t_structures}

Let $\mathcal{T}$ be a triangulated category with shift functor $[1]$. 
A pair of strictly full subcategories $(\mathcal{T}^{\leq 0}, \mathcal{T}^{\geq 0})$ of $\mathcal{T}$ is a \textbf{$t$-structure} if:
\begin{itemize}
    \item $\operatorname{Hom}(A,B) = 0$ for all $A \in \mathcal{T}^{\leq 0}$ and $B \in \mathcal{T}^{\geq 0}[-1]$,
    \item $\mathcal{T}^{\leq 0}[1] \subseteq \mathcal{T}^{\leq 0}$ and $\mathcal{T}^{\geq 0}[-1] \subseteq \mathcal{T}^{\geq 0}$,
    \item for every $E \in \mathcal{T}$, there is a distinguished triangle
    \begin{displaymath}
        \tau^{\leq 0} E \to E \to \tau^{\geq 1} E \to (\tau^{\leq 0} E)[1]
    \end{displaymath}
    with $\tau^{\leq 0} E \in \mathcal{T}^{\leq 0}$ and $\tau^{\geq 1} E \in \mathcal{T}^{\geq 0}[-1]$.
\end{itemize}
This notion was introduced in \cite{Beilinson/Berstein/Deligne/Gabber:2018}. 
The above distinguished triangle is called the \textbf{truncation triangle} of $E$ with respect to the $t$-structure. 
For any $n \in \mathbb{Z}$, $(\mathcal{T}^{\leq n}, \mathcal{T}^{\geq n})$ is also a $t$-structure on $\mathcal{T}$ where $\mathcal{T}^{\leq n} := \mathcal{T}^{\leq 0}[-n]$ and $\mathcal{T}^{\geq n} := \mathcal{T}^{\geq 0}[-n]$. 
Define the subcategories:
\begin{displaymath}
    \mathcal{T}^{-}:= \bigcup_{n=0}^\infty \mathcal{T}^{\leq n},\quad \mathcal{T}^{+} := \bigcup^\infty_{n=0} \mathcal{T}^{\geq -n},\quad \mathcal{T}^b := \mathcal{T}^{-} \cap \mathcal{T}^{+}.
\end{displaymath}
Let $F \colon \mathcal{T} \to \mathcal{T}^\prime$ be an exact functor between triangulated categories equipped with $t$-structures $(\mathcal{T}^{\leq 0}, \mathcal{T}^{\geq 0})$ and $((\mathcal{T}^\prime)^{\leq 0}, (\mathcal{T}^\prime)^{\geq 0})$. 
We say that $F$ is \textbf{right $t$-exact} if $
F(\mathcal{T}^{\leq 0}) \subseteq (\mathcal{T}^\prime)^{\leq 0}$,
and \textbf{left $t$-exact} if 
$F(\mathcal{T}^{\geq 0}) \subseteq (\mathcal{T}^\prime)^{\geq 0}$. 
If both conditions hold, then $F$ is \textbf{$t$-exact}.

A strictly full subcategory $\mathcal{A} \subseteq \mathcal{T}$ is an \textbf{aisle} if it is closed under positive shifts and extensions, and the inclusion $\mathcal{A} \to \mathcal{T}$ admits a right adjoint. 
Given a $t$-structure $(\mathcal{T}^{\leq 0}, \mathcal{T}^{\geq 0})$, the subcategory $\mathcal{T}^{\leq 0}$ is an aisle. 
By \cite[\S 1, Proposition]{Keller/Vossieck:1988}, any aisle $\mathcal{A}$ determines a $t$-structure $(\mathcal{A}, \mathcal{A}^\perp[1])$, where
\begin{displaymath}
    \mathcal{A}^\perp := \{ T \in \mathcal{T} : \operatorname{Hom}(A,T) = 0 \text{ for all } A \in \mathcal{A} \}.
\end{displaymath}
The subcategories $\mathcal{T}^{\leq 0}$ and $\mathcal{T}^{\geq 0}$ are called the \textbf{aisle} and \textbf{coaisle} of the $t$-structure, respectively. 
More generally, a \textbf{preaisle} is a strictly full subcategory closed under positive shifts and extensions. 
By \cite[Lemma 1.3 \& Corollary 1.4]{AlonsoTarrio/Lopez/Salorio:2003}, aisles are closed under direct summands and under small coproducts when these exist in $\mathcal{T}$.

Assume $\mathcal{T}$ admits small coproducts. 
A preaisle $\mathcal{A} \subseteq \mathcal{T}$ is called \textbf{cocomplete} if it is closed under all coproducts in $\mathcal{T}$. 
Given $\mathcal{S}\subseteq \mathcal{T}$, $\overline{\langle \mathcal{S} \rangle}^{(-\infty, 0]}$ is defined to be the smallest cocomplete preaisle containing $\mathcal{S}$. 
By \cite[Theorem 2.3]{Neeman:2021b}, if $\mathcal{T}$ is well generated (e.g.\ compactly generated), $\overline{\langle \mathcal{S} \rangle}^{(-\infty, 0]}$ is an aisle whenever $\mathcal{S}$ is essentially small. 
Furthermore, if $\mathcal{A}\subseteq \mathcal{T}^c$ is closed under positive shifts, then \cite[Theorem 2.3.3 \& Remark 2.3.4]{Canonaco/Haesemeyer/Neeman/Stellari:2024} (which generalizes \cite[Theorem A.1 \& Proposition A.2]{AlonsoTarrio/Lopez/Salorio:2003}) says that $\operatorname{Coprod}(\mathcal{A})$ is the aisle $\overline{\langle \mathcal{A} \rangle}^{(-\infty, 0]}$. 
An aisle $\mathcal{U}$ on $\mathcal{T}$ is \textbf{compactly generated} when there exists a collection of compact objects $\mathcal{Q} \subseteq \mathcal{T}^c$ satisfying $\overline{\langle \mathcal{Q} \rangle}^{(-\infty, 0]} = \mathcal{U}$. 
In this case, we say $\mathcal{U}$ is compactly generated by $\mathcal{Q}$. 
We say a $t$-structure is \textbf{compactly generated} if its aisle is as such. 
For instance, if $G \in \mathcal{T}^c$, then 
\begin{displaymath}
    \operatorname{Coprod}( \{ G[n] : n\geq 0 \}) = \overline{\langle G \rangle}^{(-\infty, 0]} .
\end{displaymath}

Consider a pair of $t$-structures $(\mathcal{T}_1^{\leq 0},\mathcal{T}_1^{\geq 0})$ and $(\mathcal{T}_2^{\leq 0},\mathcal{T}_2^{\geq 0})$ on $\mathcal{T}$.
We say they are \textbf{equivalent} if there exists $A\geq 0$ such that $\mathcal{T}_1^{\leq -A}\subseteq \mathcal{T}_2^{\leq 0}\subseteq \mathcal{T}_1^{\leq A}$.
If $\mathcal{T}$ has a single compact generator, the \textbf{preferred equivalence class} is the equivalence class of the $t$-structure compactly generated by any compact generator.
By \cite[Remark 1.19]{Neeman:2026}, the preferred equivalence class does not depend on the choice of compact generator. 

If $\mathcal{T}$ has small coproducts and is equipped with a $t$-structure $(\mathcal{T}^{\leq 0}, \mathcal{T}^{\geq 0})$, let $\mathcal{T}^-_c$ be the collection of $E\in \mathcal{T}$ such that for every $n>0$ there exists a distinguished triangle 
\begin{displaymath}
    D \to E \to F \to D[1]
\end{displaymath}
with $D\in \mathcal{T}^c$ and $F\in \mathcal{T}^{\leq -n}$. 
Moreover, let $\mathcal{T}^b_c := \mathcal{T}^b \cap \mathcal{T}^-_c$. 
Furthermore, if $\mathcal{T}$ is weakly approximable and $(\mathcal{T}^{\leq 0}, \mathcal{T}^{\geq 0})$ is in the preferred equivalence class, then $\mathcal{T}^?$ and $\mathcal{T}^\#_c$ are independent of the $t$-structure representing the equivalence class for $?\in \{-,+,b\}$ and $\# \in \{-,b\}$. 
See \cite[Remark 4.1.5]{Canonaco/Haesemeyer/Neeman/Stellari:2024}.
\subsubsection{Recollements}
\label{sec:prelim_recollements}

We briefly recall the notion of a recollement. 
See \cite[\S 1.4]{Beilinson/Berstein/Deligne/Gabber:2018} for details. 
A \textbf{recollement} is a diagram of triangulated categories and exact functors of the form 
\begin{displaymath}
        \begin{tikzcd}[column sep=6em]
            {\mathcal{D}_Z} & {\mathcal{D}} & {\mathcal{D}_U}
            \arrow["{i_\ast}" description, from=1-1, to=1-2]
            \arrow["{i^\ast}"', bend right=35, from=1-2, to=1-1]
            \arrow["{i^!}", bend left=35, from=1-2, to=1-1]
            \arrow["{j^\ast}" description, from=1-2, to=1-3]
            \arrow["{j_!}"', bend right=35, from=1-3, to=1-2]
            \arrow["{j_\ast}", bend left=35, from=1-3, to=1-2]
        \end{tikzcd}
    \end{displaymath}
satisfying:
\begin{itemize}
    \item $i^\ast \dashv i_\ast \dashv i^!$ and $j_! \dashv j^\ast \dashv j_\ast$ (i.e.\ adjoint triples)
    \item $i_\ast, j_!, j_\ast$ are fully faithful
    \item $\ker (j^\ast)$ coincides with the strictly full subcategory on objects of the form $i_\ast(T)$ where $T\in \mathcal{D}_Z$.
\end{itemize}
In such a case, there are distinguished triangles
\begin{displaymath}
    \begin{aligned}
        j_! j^\ast E 
        & \xrightarrow{\epsilon_E} E 
        \xrightarrow{\eta_E} i_\ast i^\ast E 
        \xrightarrow{\varphi_E} j_! j^\ast E[1],
        \\& i_\ast i^! E \to E \to j_\ast j^\ast E \to i_\ast i^! E[1]
    \end{aligned}
\end{displaymath}
which are functorial in $E\in \mathcal{D}$.
In particular, the natural transformations between these functors are given by the (co)units of the relevant adjoint pairs. 
Since $j_!$, $j^\ast$, $i_\ast$, and $i^\ast$ are left adjoints, they preserve coproducts. 
Additionally, if each triangulated category is compactly generated, $i_\ast$ and $j^\ast$ admitting right adjoints implies $i^\ast$ and $j_!$ preserve compact objects \cite[Theorem 5.1]{Neeman:1996}.
Given $E\in \mathcal{D}_Z$ and $B \in \mathcal{D}_U$, $j^\ast i_\ast E \cong 0$, $i^! j_\ast B \cong 0$, and $i^\ast j_! B \cong 0$. 

Assume $(\mathcal{D}_Z^{\leq 0}, \mathcal{D}_Z^{\geq 0})$ and $(\mathcal{D}_U^{\leq 0}, \mathcal{D}_U^{\geq 0})$ are $t$-structures respectively on $\mathcal{D}_Z$ and $\mathcal{D}_U$. 
It is possible to `glue' these aisles to obtain a new $t$-structure on $\mathcal{D}$. 
Specifically, the glued $t$-structure is given by 
\begin{displaymath}
    \begin{aligned}
        \mathcal{D}^{\leq 0} &\colonequals  \left\{ E\in \mathcal{D} : i^\ast E \in \mathcal{D}_Z^{\leq 0}, j^\ast E \in \mathcal{D}_U^{\leq 0} \right\},
        \\ \mathcal{D}^{\geq 0} &\colonequals  \left\{ E\in \mathcal{D} : i^! E \in \mathcal{D}_Z^{\geq 0}, j^\ast E \in \mathcal{D}_U^{\geq 0} \right\}.
    \end{aligned}
\end{displaymath}
Moreover, a few general facts include: $i^\ast$ and $j_!$ are right $t$-exact;  $i_\ast$ and $j^\ast$ are $t$-exact; and $i^!$ and $j_\ast$ are left $t$-exact.
See \cite[1.4.10 \& 1.3.17.(iii)]{Beilinson/Berstein/Deligne/Gabber:2018} for details.
\subsubsection{Weak approximability}
\label{sec:prelim_weak_approx}

We recall the definition of weak approximability for triangulated categories.
See \cite[Definition 1.25]{Neeman:2026}.

\begin{definition}
    \label{def:weak_approx}
    A triangulated category $\mathcal{T}$ is \textbf{weakly approximable} if there exist a compact generator $G$, a $t$-structure $(\mathcal{T}^{\leq 0},\mathcal{T}^{\geq 0})$ and an integer $A>0$ such that:
    \begin{enumerate}
        \item \label{def:weak_approx1} $G\in \mathcal{T}^{\leq A}$ and $\operatorname{Hom}(G,\mathcal{T}^{\leq -A})=0$;
        \item \label{def:weak_approx2} every $F\in \mathcal{T}^{\leq 0}$ admits a distinguished triangle $E\to F\to D\to E[1]$ with $E\in \overline{\langle G\rangle}^{[-A,A]}$ and $D\in \mathcal{T}^{\leq -1}$.
    \end{enumerate}
    We call $(G,\mathcal{T}^{\leq 0},A)$ \textbf{weak approximation data}.
\end{definition}

In our convention, compactly generated triangulated categories a priori have small coproducts.
In \Cref{def:weak_approx}, \eqref{def:weak_approx1} is the condition $G[A]\in \mathcal{T}^{\leq 0}$, $\operatorname{Hom}(G[-A],\mathcal{T}^{\leq 0})=0$ of \cite[2.9]{Burke/Neeman/Pauwels:2023}, since $\operatorname{Hom}(G[-A],\mathcal{T}^{\leq 0}) = \operatorname{Hom}(G,\mathcal{T}^{\leq -A})$.

A weakly approximable triangulated category $\mathcal{T}$ is \textbf{coherent} if, for any $t$-structure $(\mathcal{T}^{\leq 0}, \mathcal{T}^{\geq 0})$ in the preferred equivalence class, there exists an integer $N > 0$ such that every object $Y \in \mathcal{T}^-_c$ admits a distinguished triangle 
\begin{displaymath}
    X \to Y \to Z \to X[1]
\end{displaymath}
with $X \in \mathcal{T}^-_c \cap \mathcal{T}^{\leq N}$ and $Z\in \mathcal{T}^b_c \cap \mathcal{T}^{\geq 0}$.
See \cite[Definition 10.1.1]{Canonaco/Haesemeyer/Neeman/Stellari:2024}.
\subsection{Algebraic spaces}
\label{sec:preliminaries_stacks}

We follow \cite{StacksProject}. 
Throughout, we work over a fixed base scheme. 
Let $X$ be a quasi-compact quasi-separated algebraic space. 
\subsubsection{Notions}
\label{sec:prelim_notions}

An \textbf{\'{e}tale presentation} of $X$ is an \'{e}tale, finitely presented, surjective morphism to $X$ from a scheme. 
Denote by $|X|$ the underlying topological space of $X$. 
It consists of equivalence classes of morphisms from fields to $X$ \cite[\href{https://stacks.math.columbia.edu/tag/03BT}{Tag 03BT}]{StacksProject}. 
\subsubsection{Categories \& functors}
\label{sec:prelim_categories}

$\operatorname{Mod}(X)$ is the Grothendieck abelian category of sheaves of $\mathcal{O}_X$-modules on the small \'{e}tale site $X_{\textrm{\'{e}tale}}$ of $X$ \cite[\href{https://stacks.math.columbia.edu/tag/03LT}{Tag 03LT}]{StacksProject}. 
$\operatorname{Qcoh}(X)$ is the full subcategory of $\operatorname{Mod}(X)$ consisting of quasi-coherent sheaves. 
$D(X) := D(\operatorname{Mod}(X))$ is the derived category of $\operatorname{Mod}(X)$. 
$D_{\operatorname{qc}}(X)$ is the full subcategory of $D(X)$ consisting of complexes with quasi-coherent cohomology sheaves. 
$\operatorname{Perf}(X)$ is the full subcategory of perfect complexes in $D_{\operatorname{qc}}(X)$. 
If $X$ is Noetherian, then $\operatorname{coh}(X)$ is the full subcategory of $\operatorname{Mod}(X)$ consisting of coherent sheaves, and $D^?_{\operatorname{coh}}(X)$ is the full subcategory of $D(X)$ consisting of complexes with coherent cohomology sheaves with familiar decorations $?\in \{-,b,+\}$.

Let $f\colon Y \to X$ be a morphism of quasi-compact quasi-separated algebraic spaces. 
By \cite[\href{https://stacks.math.columbia.edu/tag/07A6}{Tag 07A6}]{StacksProject}, there exists an adjoint pair 
\begin{displaymath}
    \mathbf{L}f^\ast \colon D(X) \leftrightarrows D(Y) \colon \mathbf{R}f_\ast.
\end{displaymath}
By \cite[\href{https://stacks.math.columbia.edu/tag/08FA}{Tags 08FA} \& \href{https://stacks.math.columbia.edu/tag/08F4}{08F4}]{StacksProject}, $\mathbf{L}f^\ast$ and $\mathbf{R}f_\ast$ preserve quasi-coherent cohomology.
Moreover, \cite[\href{https://stacks.math.columbia.edu/tag/07A6}{Tag 07A6}]{StacksProject} says the restrictions of $\mathbf{L}f^\ast$ and $\mathbf{R}f_\ast$ form an adjoint pair on $D_{\operatorname{qc}}$. 
\subsubsection{Support}
\label{sec:preliminaries_stacks_support}

For $M \in \operatorname{Qcoh}(X)$, $\operatorname{Supp}(M) :=|p|(\operatorname{Supp}(p^\ast M)) \subseteq |X|$ where $p \colon U \to X$ is any \'{e}tale presentation.
By \cite[\href{https://stacks.math.columbia.edu/tag/07TY}{Tag 07TY}]{StacksProject}, $\operatorname{Supp}$ is independent of the \'{e}tale presentation. 
It coincides with the notion of support for abelian sheaves on the small \'{e}tale site \cite[\href{https://stacks.math.columbia.edu/tag/04K7}{Tag 04K7}]{StacksProject}.
More generally, if $E \in D_{\operatorname{qc}}(X)$, 
\begin{displaymath}
    \operatorname{Supp}(E) := \bigcup_{j \in \mathbb{Z}} \operatorname{Supp}(\mathcal{H}^j(E)) \subseteq |X|.
\end{displaymath}
Given a closed subset $Z \subseteq |X|$, $E\in D_{\operatorname{qc}}(X)$ is \textbf{supported on $Z$} if $\operatorname{Supp}(E) \subseteq Z$. 
Denote by $D_{\operatorname{qc},Z}(X)$ the strictly full subcategory of $D_{\operatorname{qc}}(X)$ consisting of objects supported on $Z$. 
If $X$ is Noetherian, we can define $D_{\operatorname{coh},Z}(X)$ analogously. 
\subsubsection{Perfect complexes}
\label{sec:prelim_perfects}

Perfect complexes are defined on the small \'{e}tale site of $X$. 
See \cite[\href{https://stacks.math.columbia.edu/tag/08G4}{Tag 08G4}]{StacksProject}. 
In particular, a complex is \textbf{strictly perfect} if it is a bounded complex whose terms are direct summands of finite free modules, whereas a complex is \textbf{perfect} if it is locally strictly perfect. 
For any $Z\subseteq |X|$ closed such that $|X|\setminus Z$ is quasi-compact: perfect complexes supported on $Z$ coincide with compacts of $D_{\operatorname{qc},Z}(X)$ and $D_{\operatorname{qc},Z}(X)$ is singly compactly generated \cite[\href{https://stacks.math.columbia.edu/tag/0AED}{Tags 0AED}, \href{https://stacks.math.columbia.edu/tag/09M8}{09M8}, \& \href{https://stacks.math.columbia.edu/tag/0AEC}{0AEC}]{StacksProject}.
\section{Auxiliary results}
\label{sec:auxillary}

\begin{lemma}
    \label{lem:closures}
    Let $\mathcal{T}$ and $\mathcal{T}^\prime$ be triangulated categories which admit small coproducts. 
    Choose $H\in \mathcal{T}$ and integers $a\leq b$.
    Then:
    \begin{enumerate}
        \item \label{lem:closures1} $\overline{\langle H\rangle}^{[a,b]}$ is closed under small coproducts, extensions, and direct summands; in fact, it is the smallest strictly full subcategory of $\mathcal{T}$ closed under these operations that contains $H[a,b]$.
        \item \label{lem:closures2} $\overline{\langle H\rangle}^{[a,b]}[s] = \overline{\langle H\rangle}^{[a-s,b-s]}$ and $\overline{\langle H\rangle}^{[a,b]} \subseteq \overline{\langle H\rangle}^{[a^\prime,b^\prime]}$ for all $s\in \mathbb{Z}$, $a^\prime\leq a$, and $b\leq b^\prime$.
        \item \label{lem:closures3} $F(\overline{\langle H\rangle}^{[a,b]}) \subseteq \overline{\langle H^\prime\rangle}^{[a+c,b+d]}$ for any small coproduct preserving exact $F\colon \mathcal{T}\to \mathcal{T}^\prime$ and $H^\prime \in \mathcal{T}^\prime$ with $F(H)\in \overline{\langle H^\prime\rangle}^{[c,d]}$.
        \item \label{lem:closures4} Let $Y\in \mathcal{T}$. If $\operatorname{Hom}(H[-k],Y)=0$ for all $a\leq k\leq b$, then $\operatorname{Hom}(X,Y)=0$ for all $X\in \overline{\langle H\rangle}^{[a,b]}$. If $H$ is compact, then $\{Y\in \mathcal{T} : \operatorname{Hom}(H,Y)=0\}$ is closed under small coproducts, extensions, and direct summands.
        \item \label{lem:closures5} $\operatorname{smd}(\operatorname{Coprod}(H[a,b])) \subseteq \operatorname{Coprod}(H[a,b+1])$.
    \end{enumerate}
\end{lemma}

\begin{proof}
    First we prove \eqref{lem:closures1}.
    By definition, $\overline{\langle H\rangle}^{[a,b]} := \operatorname{smd}(\operatorname{Coprod}(H[a,b]))$. 
    Let $\Lambda$ be a set.
    Choose $X_\lambda \in \overline{\langle H\rangle}^{[a,b]}$ where $\lambda \in \Lambda$. 
    For each $\lambda \in \Lambda$, there exists $X^\prime_\lambda \in \mathcal{T}$ such that $X_\lambda \oplus X^\prime_\lambda\in \operatorname{Coprod}(H[a,b])$.
    Since $\operatorname{Coprod}(H[a,b])$ is closed under small coproducts, $\oplus_{\lambda\in \Lambda} (X_\lambda \oplus X^\prime_\lambda)\in \operatorname{Coprod}(H[a,b])$. 
    Note that $\oplus_{\lambda\in \Lambda}X_\lambda$ is a direct summand of $\oplus_{\lambda\in \Lambda} (X_\lambda \oplus X^\prime_\lambda)$. 
    Hence, $\overline{\langle H\rangle}^{[a,b]}$ is closed under small coproducts. 

    Consider a distinguished triangle 
    \begin{displaymath}
        A \to B \to C \to A[1]
    \end{displaymath}
    where $A,C\in \overline{\langle H\rangle}^{[a,b]}$. 
    We can find $A^\prime,C^\prime$ such that $A\oplus A^\prime, C\oplus C^\prime \in \operatorname{Coprod}(H[a,b])$. 
    There exist distinguished triangles
    \begin{displaymath}
        A^\prime \xrightarrow{1_{A^\prime}} A^\prime \to 0 \to A^\prime[1]
    \end{displaymath}
    and \begin{displaymath}
        0 \to C^\prime \xrightarrow{1_{C^\prime}} C^\prime \to 0[1].
    \end{displaymath}
    Taking the direct sum of these distinguished triangles yields a distinguished triangle 
    \begin{displaymath}
        \begin{aligned}
            A\bigoplus A^\prime \bigoplus 0 
            \to B \bigoplus A^\prime \bigoplus C^\prime
            \to C \bigoplus 0 \bigoplus C^\prime \to A[1]\bigoplus A^\prime[1] \bigoplus 0.
        \end{aligned}
    \end{displaymath}
    See \cite[Proposition 1.2.1]{Neeman:2001}. 
    Since $A\oplus A^\prime, C\oplus C^\prime\in  \operatorname{Coprod}(H[a,b])$, it follows that $B \oplus A^\prime \oplus C^\prime\in \operatorname{Coprod}(H[a,b])$ because the category is closed under extensions.
    Consequently, $B \in \overline{\langle H\rangle}^{[a,b]}$.

    To see that $\overline{\langle H\rangle}^{[a,b]}$ is closed under direct summands, use the fact that a direct summand of a direct summand remains a direct summand.

    Lastly, we show the minimality claim. 
    Let $\mathcal{B}$ be a strictly full subcategory of $\mathcal{T}$ closed under small coproducts, extensions, and direct summands that contains $H[a,b]$.
    In this case, $\operatorname{Coprod}(H[a,b])\subseteq \mathcal{B}$. 
    Indeed, $\mathcal{B}$ is closed under small coproducts and extensions, and it contains $H[a,b]$. 
    Moreover, $\operatorname{smd}(\operatorname{Coprod}(H[a,b]))\subseteq \mathcal{B}$ because $\mathcal{B}$ is closed under direct summands. 

    Second we prove \eqref{lem:closures2}. 
    The autoequivalence $[s]\colon \mathcal{T} \to \mathcal{T}$ preserves extensions, small coproducts, and direct summands. 
    Hence, $\overline{\langle H\rangle}^{[a,b]}[s]$ is the smallest strictly full subcategory containing $(H[a,b])[s]$ which is closed under extensions, small coproducts, and direct summands.
    However, shifting by $s$ yields 
    \begin{displaymath}
        \begin{aligned}
            (H[a,b])[s] 
            &= \{ H [-k][s] : a\leq k \leq b \} 
            \\&= \{ H [-k+s] : a\leq k \leq b \}
            \\&=\{ H [-l] : a-s\leq l \leq b-s \}
            \\&=: H[a-s,b-s].
        \end{aligned}
    \end{displaymath}
    It follows that $\overline{\langle H\rangle}^{[a,b]}[s] = \overline{\langle H\rangle}^{[a-s,b-s]}$. 
    Moreover, as $H[a,b]\subseteq H[a^\prime,b^\prime]$, \eqref{lem:closures1} implies $\overline{\langle H\rangle}^{[a,b]} \subseteq \overline{\langle H\rangle}^{[a^\prime,b^\prime]}$.

    Third we prove \eqref{lem:closures3}.
    Choose $a\leq k\leq b$.
    Note that $F$ is exact and $F(H)\in \overline{\langle H^\prime\rangle}^{[c,d]}$.
    Hence, by \eqref{lem:closures2},
    \begin{displaymath}
        F(H[-k])\cong F(H)[-k]
        \in \overline{\langle H^\prime\rangle}^{[c,d]}[-k] 
        = \overline{\langle H^\prime\rangle}^{[c+k,d+k]}\subseteq \overline{\langle H^\prime\rangle}^{[a+c,b+d]}.
    \end{displaymath}
    Set $\mathcal{S}$ to be the full subcategory of $E\in \mathcal{T}$ such that $F(E)\in \overline{\langle H^\prime\rangle}^{[a+c,b+d]}$.
    It follows that $H[a,b]\subseteq \mathcal{S}$.
    By \eqref{lem:closures1}, $\overline{\langle H^\prime\rangle}^{[a+c,b+d]}$ is strictly full and closed under small coproducts, extensions, and direct summands.
    Since $F$ preserves small coproducts, $\mathcal{S}$ has the same properties.
    By minimality, \eqref{lem:closures1} implies $\overline{\langle H\rangle}^{[a,b]}\subseteq \mathcal{S}$.
    Thus, \eqref{lem:closures3} follows.

    Next we prove \eqref{lem:closures4}. 
    It is easy to see that $\{E : \operatorname{Hom}(E,Y)=0\}$ is strictly full. 
    Let $\Lambda$ be a set. 
    Choose $X_\lambda \in \{E : \operatorname{Hom}(E,Y)=0\}$.
    By the universal property of coproducts, there exists an isomorphism
    \begin{displaymath}
        \operatorname{Hom}(\bigoplus_{\lambda \in \Lambda} X_\lambda, Y) 
        \cong \prod_{\lambda \in \Lambda} \operatorname{Hom}(X_\lambda, Y)
        \cong 0.
    \end{displaymath} 
    See \cite[Example 1.1.13]{Neeman:2001} applied to $\mathcal{T}^{op}$. 
    The last isomorphism follows from the fact that each $X_\lambda \in \{E : \operatorname{Hom}(E,Y)=0\}$.
    Hence, $\{E : \operatorname{Hom}(E,Y)=0\}$ is closed under small coproducts. 
    Let $A,B\in \{E : \operatorname{Hom}(E,Y)=0\}$.
    Consider an extension $C$ given by a distinguished triangle 
    \begin{displaymath}
        A \to C \to B \to A[1].
    \end{displaymath}
    Apply $\operatorname{Hom}(-,Y)$ to obtain a long exact sequence in Hom sets 
    \begin{displaymath}
        \cdots \to \operatorname{Hom}(B,Y) \to \operatorname{Hom}(C,Y) \to \operatorname{Hom}(A,Y) \to \cdots.
    \end{displaymath}
    Hence, $\operatorname{Hom}(C,Y) \cong 0$ if 
    \begin{displaymath}
        \operatorname{Hom}(A,Y) \cong \operatorname{Hom}(B,Y) \cong 0.
    \end{displaymath}
    This implies $\{E : \operatorname{Hom}(E,Y)=0\}$ is closed under extensions.
    Moreover, if $A\oplus B \in \{E : \operatorname{Hom}(E,Y)=0\}$, then 
    \begin{displaymath}
        \operatorname{Hom}(A\oplus B,Y)\cong \operatorname{Hom}(A,Y) \bigoplus \operatorname{Hom}(B,Y) \cong 0.
    \end{displaymath} 
    Thus, $\{E : \operatorname{Hom}(E,Y)=0\}$ is closed under direct summands. 
    The hypothesis asserts that $H[a,b]\subseteq \{E : \operatorname{Hom}(E,Y)=0\}$.
    By \eqref{lem:closures1}, $\overline{\langle H \rangle}^{[a,b]}\subseteq \{E : \operatorname{Hom}(E,Y)=0\}$.
    A similar argument with $H$ compact proves the second claim for \eqref{lem:closures4}.
    Indeed, the compactness of $H$ gives the closure under coproducts, whereas the other conditions are analogous.

    Lastly we prove \eqref{lem:closures5}. 
    Let $X\in \operatorname{smd}(\operatorname{Coprod}(H[a,b]))$.
    Choose $X^\prime$ such that $X\oplus X^\prime \in \operatorname{Coprod}(H[a,b])$.
    The so-called Eilenberg swindle yields an isomorphism
    \begin{displaymath}
        \begin{aligned}
            X \oplus (\bigoplus_{n\in \mathbb{N}} (X\oplus X^\prime)) 
            &\cong X \oplus (\bigoplus_{n\in \mathbb{N}} (X^\prime \oplus X)) 
            \\&\cong X \oplus (X^\prime \oplus X) \oplus (X^\prime \oplus X) \oplus \cdots
            \\&\cong (X \oplus X^\prime) \oplus (X \oplus X^\prime) \oplus \cdots
            \\&\cong \bigoplus_{n\in \mathbb{N}} (X \oplus X^\prime).
        \end{aligned}
    \end{displaymath}
    Consequently, there exists a distinguished triangle 
    \begin{displaymath}
        X \to X \oplus (\bigoplus_{n\in \mathbb{N}} (X\oplus X^\prime)) \to \bigoplus_{n\in \mathbb{N}}(X\oplus X^\prime) \to X[1].
    \end{displaymath}
    Rotating backwards yields 
    \begin{displaymath}
        (\bigoplus_{n\in \mathbb{N}}( X\oplus X^\prime))[-1] 
        \to X \to X \oplus (\bigoplus_{n\in \mathbb{N}} (X\oplus X^\prime)) \to \bigoplus_{n\in \mathbb{N}}( X\oplus X^\prime).
    \end{displaymath}
    Since $[a,b]\subseteq [a,b+1]$, $\operatorname{Coprod}(H[a,b]) \subseteq \operatorname{Coprod}(H[a,b+1])$.
    Observe that 
    \begin{displaymath}
        \begin{aligned}
            (\bigoplus_{n\in \mathbb{N}} (X\oplus X^\prime))[-1]
            &\in \operatorname{Coprod}(H[a,b])[-1] 
            \\&= \operatorname{Coprod}(H[a+1,b+ 1])
            \\&\subseteq \operatorname{Coprod}(H[a,b+1]).
        \end{aligned}
    \end{displaymath}
    Therefore, 
    \begin{displaymath}
        \begin{aligned}
            X 
            &\in \operatorname{Coprod}(H[a,b+1]) \star \operatorname{Coprod}(H[a,b])
            \\&\subseteq \operatorname{Coprod}(H[a,b+1]) \star \operatorname{Coprod}(H[a,b+1])
            \\&\subseteq \operatorname{Coprod}(H[a,b+1]).
        \end{aligned}
    \end{displaymath}
    This completes the proof.
\end{proof}

\begin{remark}
    \label{rmk:octahedral}
    We use the octahedral axiom in the following ways.
    Let $X\xrightarrow{f} Y\xrightarrow{g} Z$ be composable.
    \begin{enumerate}
        \item \label{rmk:octahedraloc} Choose distinguished triangles $X\xrightarrow{f} Y\to C_f\to X[1]$, $Y\xrightarrow{g} Z\xrightarrow{p_g} C_g\to Y[1]$ and $X\xrightarrow{gf} Z\xrightarrow{p_{gf}} C_{gf}\to X[1]$. There is a distinguished triangle $C_f\to C_{gf}\xrightarrow{h} C_g\to C_f[1]$ with $h\circ p_{gf} = p_g$. See e.g.\ \cite[Proposition 1.4.6]{Neeman:2001}.
        \item \label{rmk:octahedralof} Choose distinguished triangles $F_f\to X\xrightarrow{f} Y\to F_f[1]$, $F_g\to Y\xrightarrow{g} Z\to F_g[1]$ and $F_{gf}\to X\xrightarrow{gf} Z\to F_{gf}[1]$. There is a distinguished triangle $F_f\to F_{gf}\to F_g\to F_f[1]$. Indeed, take the distinguished triangle $C_f\to C_{gf}\xrightarrow{h} C_g\to C_f[1]$ and shift by $[-1]$. Here we use that $F_? \cong C_?[-1]$.
    \end{enumerate}
\end{remark}

\begin{lemma}
    \label{lem:aisle}
    Let $(\mathcal{T}^{\leq 0},\mathcal{T}^{\geq 0})$ be a $t$-structure on a triangulated category $\mathcal{T}$.
    Consider a distinguished triangle  
    \begin{displaymath}
        E\to F\to D\to E[1]
    \end{displaymath}
    where $F\in \mathcal{T}^{\leq 0}$ and $D\in \mathcal{T}^{\leq -m}$ for some $m\geq 1$.
    Then $E\in \mathcal{T}^{\leq 0}$.
\end{lemma}

\begin{proof}
    By rotating backwards, there exists a distinguished triangle  
    \begin{displaymath}
       D[-1] \to E\to F\to D.
    \end{displaymath}
    Note that $D[-1]\in \mathcal{T}^{\leq 1-m} \subseteq \mathcal{T}^{\leq 0}$.
    Since aisles are closed under extensions, $E\in \mathcal{T}^{\leq 0}$.
\end{proof}

\begin{lemma}
    \label{lem:iterate}
    Let $(H,\mathcal{T}^{\leq 0},A)$ be weak approximation data for $\mathcal{T}$.
    For every $F\in \mathcal{T}^{\leq 0}$ and every $m\geq 1$, there exists a distinguished triangle 
    \begin{displaymath}
        E_m\to F\to D_m\to E_m[1]
    \end{displaymath}
    with $E_m\in \overline{\langle H\rangle}^{[1-m-A,A]} \cap \mathcal{T}^{\leq 0}$ and $D_m\in \mathcal{T}^{\leq -m}$. 
\end{lemma}

\begin{proof}
    This follows from \cite[Corollary 3.2(1)]{Neeman:2026} with weak approximation data for $\mathcal{T}$.
    To be self-contained, we give a proof.
    By \Cref{lem:aisle}, for any desired distinguished triangle 
    \begin{displaymath}
        E_m\to F\to D_m\to E_m[1],
    \end{displaymath}
    it follows that $E_m\in \mathcal{T}^{\leq 0}$.
    Hence, it suffices to produce the desired distinguished triangle.
    We argue by induction on $m$. 
    The base case $m=1$ is \Cref{def:weak_approx}\eqref{def:weak_approx2}.

    Assume that the desired distinguished triangle exists for $m$, i.e.\ a distinguished triangle 
    \begin{displaymath}
        E_m\to F\xrightarrow{f} D_m\to E_m[1]
    \end{displaymath}
    with $E_m\in \overline{\langle H\rangle}^{[1-m-A,A]} \cap \mathcal{T}^{\leq 0}$ and $D_m\in \mathcal{T}^{\leq -m}$. 
    Since $D_m[-m]\in \mathcal{T}^{\leq 0}$, \Cref{def:weak_approx}\eqref{def:weak_approx2} yields a distinguished triangle 
    \begin{displaymath}
        E^\prime \to D_m[-m]\to D^\prime \to E^\prime[1]
    \end{displaymath}
    where $E^\prime \in \overline{\langle H\rangle}^{[-A,A]}$ and $D^\prime \in \mathcal{T}^{\leq -1}$.
    After shifting by $[m]$, we have a distinguished triangle 
    \begin{displaymath}
        E^\prime[m]\to D_m\xrightarrow{g} D^\prime[m]\to E^\prime[m+1]
    \end{displaymath}
    where $E^\prime[m]\in \overline{\langle H\rangle}^{[-A-m,A-m]}$ and $D^\prime[m]\in \mathcal{T}^{\leq -1-m}$.
    Set $D_{m+1} := D^\prime[m]$. 
    Complete the composite $g\circ f \colon F\to D^\prime[m]$ to a distinguished triangle,
    \begin{displaymath}
        F\to D^\prime[m] \to R \to F[1].
    \end{displaymath}
    Set $E_{m+1}:=R[-1]$. 
    The cocones of $f$, $g$, and $g\circ f$ are respectively $E_m$, $E^\prime[m]$, and $E_{m+1}$. 
    By \Cref{rmk:octahedral}\eqref{rmk:octahedralof}, this yields a distinguished triangle 
    \begin{displaymath}
        E_m \to E_{m+1} \to E^\prime [m] \to E_m [1].
    \end{displaymath}
    By \Cref{lem:closures}\eqref{lem:closures1}\eqref{lem:closures2},
    \begin{displaymath}
        \begin{aligned}
            E_{m+1} 
            & \in \overline{\langle H\rangle}^{[1-m-A,A]} \star \overline{\langle H\rangle}^{[-m-A,A-m]}
            \\& \subseteq \overline{\langle  H\rangle}^{[-m-A,A]} 
            \\&= \overline{\langle H\rangle}^{[1-(m+1)-A,A]}.
        \end{aligned}
    \end{displaymath}
    This completes the proof.
\end{proof}

\begin{lemma}
    \label{lem:hom_vanishing}
    Let $\mathcal{T}$ be a triangulated category admitting small coproducts. 
    Choose $H\in \mathcal{T}^c$.
    Denote by $\mathcal{T}^{\leq 0}$ the aisle compactly generated by $H$.
    Assume that $\operatorname{Hom}(H,H[n])=0$ for all $n\geq n_0$.
    Then $\operatorname{Hom}(H,\mathcal{T}^{\leq -n_0})=0$.
\end{lemma}

\begin{proof}
    This is \cite[Remark 1.24]{Neeman:2026}; cf.\ \cite[Lemma 3.5(1)]{Burke/Neeman/Pauwels:2023}.
    On one hand, 
    \begin{displaymath}
        \begin{aligned}
            \mathcal{T}^{\leq -n_0} 
            &= \mathcal{T}^{\leq 0}[n_0] 
            \\&= \operatorname{Coprod}(\{H[n] : n\geq n_0\}).
        \end{aligned}
    \end{displaymath}
    On the other hand, the strictly full subcategory 
    \begin{displaymath}
        \{Y \in \mathcal{T} : \operatorname{Hom}(H,Y)=0\}
    \end{displaymath}
    contains $H[n]$ for $n\geq n_0$. 
    Moreover, by \Cref{lem:closures}\eqref{lem:closures4}, this subcategory above is closed under small coproducts and extensions.
    Consequently, the subcategory above contains $\mathcal{T}^{\leq -n_0}$.
    Thus, the desired claim follows.
\end{proof}
\section{Lifts to aisles}
\label{sec:lifts}

\begin{setup}
    \label{setup:recollement}
    Consider a recollement of singly compactly generated triangulated categories: 
    \begin{displaymath}
        \begin{tikzcd}[column sep=6em]
            {\mathcal{D}_Z} & {\mathcal{D}} & {\mathcal{D}_U.}
            \arrow["{i_\ast}" description, from=1-1, to=1-2]
            \arrow["{i^\ast}"', bend right=35, from=1-2, to=1-1]
            \arrow["{i^!}", bend left=35, from=1-2, to=1-1]
            \arrow["{j^\ast}" description, from=1-2, to=1-3]
            \arrow["{j_!}"', bend right=35, from=1-3, to=1-2]
            \arrow["{j_\ast}", bend left=35, from=1-3, to=1-2]
        \end{tikzcd}
    \end{displaymath}
    For every $E\in \mathcal{D}$, there are distinguished triangles
    \begin{equation}
        \label{eq:gluing_triangles}
        \begin{aligned}
            j_! j^\ast E 
            & \xrightarrow{\epsilon_E} E 
            \xrightarrow{\eta_E} i_\ast i^\ast E 
            \xrightarrow{\varphi_E} j_! j^\ast E[1],
            \\& i_\ast i^! E \to E \to j_\ast j^\ast E \to i_\ast i^! E[1].
        \end{aligned}
    \end{equation}
    Here $\epsilon$ is the counit of $j_! \dashv j^\ast$ and $\eta$ is the unit of $i^\ast \dashv i_\ast$.
\end{setup}

\begin{lemma}
    \label{lem:glued}
    Assume \Cref{setup:recollement}.
    Consider $t$-structures $(\mathcal{D}_Z^{\leq 0},\mathcal{D}_Z^{\geq 0})$ and $(\mathcal{D}_U^{\leq 0},\mathcal{D}_U^{\geq 0})$ respectively on $\mathcal{D}_Z$ and $\mathcal{D}_U$. 
    Denote by $(\mathcal{D}^{\leq 0},\mathcal{D}^{\geq 0})$ the glued $t$-structure.
    For every $n\in \mathbb{Z}$,
    \begin{displaymath}
        \mathcal{D}^{\leq n} = \{E\in \mathcal{D} :\ i^\ast E\in \mathcal{D}_Z^{\leq n}\ \text{and}\ j^\ast E\in \mathcal{D}_U^{\leq n}\}.
    \end{displaymath}
    In particular,
    \begin{displaymath}
        i^\ast \mathcal{D}^{\leq n}\subseteq \mathcal{D}_Z^{\leq n},
        \qquad 
        j^\ast \mathcal{D}^{\leq n}\subseteq \mathcal{D}_U^{\leq n},
        \qquad 
        i_\ast \mathcal{D}_Z^{\leq n}\subseteq \mathcal{D}^{\leq n},
        \qquad 
        j_! \mathcal{D}_U^{\leq n}\subseteq \mathcal{D}^{\leq n}.
    \end{displaymath}
\end{lemma}

\begin{proof}
    If $n=0$, then this is the definition of the glued aisle.
    Since $i^\ast$ and $j^\ast$ commute with shifts, 
    \begin{displaymath}
        \mathcal{D}^{\leq n} = \{E\in \mathcal{D} :\ i^\ast E\in \mathcal{D}_Z^{\leq n}\ \text{and}\ j^\ast E\in \mathcal{D}_U^{\leq n}\}.
    \end{displaymath}
    Moreover, the functors $i^\ast, j^\ast, i_\ast, j_!$ are right $t$-exact for the $n=0$ case.
    After shifting, the desired containments follow.
\end{proof}

