\section{Introduction and main results}

The Riemann--Siegel theta-function is
\[
 \vartheta(t)=\ImPart\log\Gamma\left(\frac14+\frac{it}{2}\right)
              -\frac t2\log\pi,
\]
where the branch of the logarithm is chosen continuously.  For all
sufficiently large $t$, the function $\vartheta$ is strictly increasing.
We use the continuously interpolated Gram points $t_u$, defined by
\begin{equation}\label{eq:gram-definition}
 \vartheta(t_u)=\pi(u-1).
\end{equation}
At positive integral values $u=k$, these are the Gram points, with an
inessential index shift relative to another common convention.  For a
fixed integer $d\geq1$, we consider the shifts $t_k^d$.

Discrete questions involving Gram points arise naturally in the value
distribution of the zeta-function; see, for example,
\cite{Korolev2016,KorolevLaurincikas2019,Laurincikas2023}.
Related uniform-distribution results for the ordinates of $a$-points of
functional-equation factors, encompassing ordinary Gram points, were
obtained by Sourmelidis, Steuding, and Suriajaya
\cite[Corollary 1]{SourmelidisSteudingSuriajaya2022Indag}.
For $d\geq2$, the shifts $t_k^d$ are superlinear, and a continuous
mean-square theorem
cannot simply be sampled at the integers: differentiation of a
composition with the map $u\mapsto t_u^d$ introduces an unbounded
derivative.
We therefore estimate the discrete exponential sums directly.  This is
also the central theme in work on discrete moments along polynomial
shifts; see Sourmelidis \cite{Sourmelidis2020}.

The higher derivatives of $t_u$ and the qualitative uniform distribution
of $t_k^d$ modulo one were established by Dundulis, Garunk\v{s}tis,
Laurin\v{c}ikas, and \v{S}im\.{e}nas in the companion preprint
\cite{DundulisEtAl2026GramDerivatives}.  That preprint treats the
mean-square Euler-product approximation as a conjectural input.  In the
present paper we use its Gram-power derivative asymptotic to obtain a
quantitative exponential-sum estimate, from which we prove the
Euler-product approximation, the second moment, and universality in the
regions stated below.  

For $Y\geq2$, define the finite Euler product
\begin{equation}\label{eq:euler-product}
 \zeta_Y(s):=\prod_{p\leq Y}(1-p^{-s})^{-1}.
\end{equation}
Let $\Sy_Y$ be the set of positive integers all of whose prime factors
are at most $Y$.  Since only finitely many primes occur, one has the
absolutely convergent expansion
\begin{equation}\label{eq:smooth-series}
 \zeta_Y(s)=\sum_{m\in\Sy_Y}m^{-s},\qquad \RePart s>0.
\end{equation}

For a fixed integer $d\geq1$, set
\begin{equation}\label{eq:main-parameters}
 \eta_d:=\frac{1}{2^{d+1}-2},\qquad
 \sigma_d:=1-\frac{\eta_d}{d},\qquad
 \sigma_d^*:=\begin{cases}
  7/8,&d=2,\\
  \sigma_d,&d\ne2.
 \end{cases}
\end{equation}
The value $\sigma_d$ is supplied by the general derivative-test
argument.  Our baseline mean-square approximation is as follows.

\begin{theorem}[Unconditional Euler-product approximation]
\label{thm:unconditional-approximation}
Let $d\geq1$ be fixed and let $K$ be a compact set with
\[
 K\subset\{s\in\C:\sigma_d<\RePart s<1\}.
\]
Then
\begin{equation}\label{eq:main-approximation}
 \lim_{Y\to\infty}\limsup_{N\to\infty}\sup_{s\in K}
 \frac1N\sum_{k=2}^{N}
 \left|\zeta(s+it_k^d)-\zeta_Y(s+it_k^d)\right|^2=0.
\end{equation}
\end{theorem}

The quadratic case admits a stronger range because equal frequency
ratios can be grouped before the off-diagonal is estimated.

\begin{theorem}[Quadratic improvement]
\label{thm:quadratic-improvement}
Let $K$ be a compact set with
\[
 K\subset\{s\in\C:\tfrac78<\RePart s<1\}.
\]
Then \eqref{eq:main-approximation} holds with $d=2$.
\end{theorem}

The linear case has $\sigma_1=1/2$.  The next three left endpoints
supplied by the theorem are
\begin{equation}\label{eq:first-boundaries}
 \sigma_2=\frac{11}{12},\qquad
 \sigma_3=\frac{41}{42},\qquad
 \sigma_4=\frac{119}{120}.
\end{equation}
Here $11/12$ is the baseline value for $d=2$;
\cref{thm:quadratic-improvement} replaces it by $7/8$.  The method does
not include the boundary line $\RePart s=7/8$.

\begin{theorem}[Conditional Euler-product approximation]
\label{thm:conditional-approximation}
Assume the Lindelöf hypothesis.  Let $d\geq1$ be fixed and let $K$ be a
compact set with
\[
 K\subset\{s\in\C:\tfrac12<\RePart s<1\}.
\]
Then \eqref{eq:main-approximation} holds.
\end{theorem}

The approximation theorems imply the desired second-moment formula.

\begin{corollary}[Discrete second moment]
\label{cor:second-moment}
Let $d\geq1$ be fixed.  If
$K\subset\{s\in\C:\sigma_d^*<\RePart s<1\}$ is compact, then
\begin{equation}\label{eq:moment-limit}
 \lim_{N\to\infty}\sup_{s\in K}
 \left|\frac1N\sum_{k=2}^{N}|\zeta(s+it_k^d)|^2
       -\zeta(2\RePart s)\right|=0.
\end{equation}
Assuming the Lindelöf hypothesis, the same conclusion holds for every
compact set
$K\subset\{s\in\C:1/2<\RePart s<1\}$.
\end{corollary}

\begin{theorem}[Discrete universality along Gram powers]
\label{thm:universality}
Let $d\geq1$ be fixed, let
$K\subset\{s\in\C:\sigma_d^*<\RePart s<1\}$ be a compact set with
connected complement,
and let $f$ be continuous and nonvanishing on $K$ and analytic in its
interior.  Then, for every $\varepsilon>0$,
\begin{equation}\label{eq:universality}
 \liminf_{N\to\infty}\frac1N\#\left\{2\leq k\leq N:
 \max_{s\in K}|\zeta(s+it_k^d)-f(s)|<\varepsilon\right\}>0.
\end{equation}
Assuming the Lindelöf hypothesis, the same statement holds for every
compact set
$K\subset\{s\in\C:1/2<\RePart s<1\}$ with connected complement.
\end{theorem}

  The rest of the paper gives proofs of these statements.

