		H=\frac1L\int_0^L h(t,x)\dx=\frac1L\int_0^L h_0(x)\dx.
	\end{align}
	The spatially constant part of $p$ is determined by the condition that the right-hand side of \eqref{eq:beam} has zero mean. In particular, we do not independently impose zero spatial mean on the total pressure. The mechanical energy and fluid dissipation are
	\begin{align}
		\cE(t)&=\frac{\rho_f}{2}\norm{\bu(t)}_{L^2(\Omega_h(t))}^2
		+\frac{\rho_s}{2}\norm{\partial_t h (t)}_{L_\sharp^2(0,L)}^2
		+\frac\alpha2\norm{\partial_x^2 h (t)}_{L_\sharp^2(0,L)}^2
		+\frac\beta2\norm{\partial_x h (t)}_{L_\sharp^2(0,L)}^2,\\
		\cD(t)&=\norm{\nabla\bu(t)}_{L^2(\Omega_h(t))}^2.
	\end{align}
	Strong solutions satisfy
	\begin{align}
		\cE(t)+\mu\int_0^t\cD(s)\,\mathrm ds=\cE(0).\label{eq:energy-identity}
	\end{align}
	The equality $2\int_{\Omega_h}|D\bu|^2=\int_{\Omega_h}|\nabla\bu|^2$ used here follows from the particular no-slip traces in \eqref{eq:boundary}.

	\subsection{Main results}

	We use the standard notation $L^p$ and $W^{k,p}$ for Lebesgue and Sobolev spaces, and write $H^s=W^{s,2}$ for $s\geq0$, with noninteger orders understood in the fractional Sobolev sense. The same notation is used for scalar-, vector-, and matrix-valued functions. For integers $k\geq1$, $H_\sharp^k(0,L)$ consists of the functions in $H^k(0,L)$ whose derivatives of orders $0,\ldots,k-1$ have matching endpoint traces. Fractional periodic Sobolev spaces are defined by the inhomogeneous Fourier weights with frequencies in $(2\pi/L)\mathbb Z$. For $s>0$, we set $H_\sharp^{-s}(0,L)=(H_\sharp^s(0,L))'$.
	For a Banach space $X$, the spaces $L^q(0,T;X)$ and $W^{k,q}(0,T;X)$ have their usual Bochner and Bochner--Sobolev meanings, while $C([0,T];X)$ denotes continuity in the norm of $X$.

	For a positive height, define
	\begin{align*}
		\Omega_1=(0,L)\times(0,1),\qquad
		\chi_h(t,x,z)=(x,h(t,x)z).
	\end{align*}
	Thus $\chi_h(t,\cdot)$ maps $\Omega_1$ onto $\Omega_h(t)$. For a function $f$ on the moving domain, we write $\widehat f(t,x,z)=f(t,x,h(t,x)z)$. Measurability in time is understood after this pullback. For $1\leq q<\infty$ and $s\geq0$, we use the physical-domain norm
	\begin{align*}
		\norm{f}_{L^q(0,T;H^s(\Omega_h))}
		=
		\left(
		\int_0^T
		\norm{f(t)}_{H^s(\Omega_h(t))}^q
		\dt
		\right)^{1/q},
	\end{align*}
	with the essential-supremum convention when $q=\infty$. The analogous convention is used for $L^p$ and $W^{k,p}$ in place of $H^s$. We interpret $f\in C([0,T];H^1(\Omega_h))$ as $\widehat f\in C([0,T];H^1(\Omega_1))$.

	\begin{definition}\label{def:strong}
		A strong solution to \eqref{eq:model} on $[0,T]$ is a triple $(h,\bu,p)$ with positive continuous height and
		\begin{gather}
			\bu\in C([0,T];H^1(\Omega_h))\cap L^2(0,T;H^2(\Omega_h)),\ 
			\partial_t\bu\in L^2(0,T;L^2(\Omega_h)),\\
			p\in L^2(0,T;H^1(\Omega_h)),\nonumber\\
			h\in C([0,T];H_\sharp^3(0,L))\cap L^2(0,T;H_\sharp^{7/2}(0,L)),\\
			\partial_th\in C([0,T];H_\sharp^1(0,L))\cap L^2(0,T;H_\sharp^{3/2}(0,L)),\nonumber\\
			\partial_t^2h\in L^2(0,T;H_\sharp^{-1/2}(0,L)).\nonumber
		\end{gather}
		The fluid equations hold in $L^2(0,T;L^2(\Omega_h))$, the beam equation holds in $L^2(0,T;H_\sharp^{-1/2}(0,L))$, and the boundary conditions hold in the trace sense. The prescribed initial values are attained in the indicated continuous spaces. The pressure constant is fixed by the mean of the beam equation.
	\end{definition}

	The initial height and beam velocity are denoted by $h_0=h(0,\cdot)$ and $h_1=\partial_th(0,\cdot)$, respectively. The data satisfy
	\begin{subequations}\label{eq:data}
		\begin{gather}
			h_0\in H_\sharp^3(0,L),\quad h_1\in H_\sharp^1(0,L),\quad
			\bu_0\in H^1(\Omega_{h_0}),\quad m_0:=\min_{x\in[0,L]}h_0(x)>0,\label{eq:data-regularity}\\
			\int_0^Lh_1\dx=0,\qquad \Div\bu_0=0\quad\text{in }\Omega_{h_0},\\
			\bu_0(x,0)=0,\qquad \bu_0(x,h_0(x))=h_1(x)\be_2.
		\end{gather}
	\end{subequations}
	We first establish a quantitative lower bound for the gap on every finite interval of existence.
	\begin{theorem}[Quantitative distance estimate]
		\label{thm:separation}
		Let $(h,\bu,p)$ be a solution in Definition~\ref{def:strong} on $[0,T_*)$. Set
		\begin{align}
			\cS(t)=\int_0^L\frac{\dx}{h(t,x)}.
		\end{align}
		There exist $C_1,C_2>0$, depending only on $\cE(0),H,L,\rho_f,\rho_s,\mu,\alpha,\beta$, such that
		\begin{align}
			\cS(t)\leq \mathcal R(t):=C_1(1+\cS(0))e^{C_2t},
			\qquad 0\leq t<T_*, \label{eq:entropy-bound}
		\end{align}
		and
		\begin{align}
			\min_{x\in[0,L]}h(t,x)\geq
			\left(\frac{2\mathcal R(t)}L+\frac{2\cE(0)}{3\alpha}\mathcal R(t)^3\right)^{-1},
			\qquad 0\leq t<T_*.\label{eq:gap-bound}
		\end{align}
		These constants are independent of any assumed positive lower bound for the evolving height.
	\end{theorem}

	By the separation estimate in Theorem~\ref{thm:separation}, together with the global regularity estimate, we obtain the following result.
	\begin{theorem}[Global strong solution]\label{thm:global}
		Let the initial data $(\bu_0,h_0,h_1)$ satisfy \eqref{eq:data}. Then system~\eqref{eq:model} has a unique global solution in the class of Definition~\ref{def:strong}. It satisfies the energy identity~\eqref{eq:energy-identity} and the distance estimates~\eqref{eq:entropy-bound}--\eqref{eq:gap-bound}. For every finite $T>0$,
		\begin{align}
			&\sup_{0\leq t\leq T}\left(
			\norm{\bu(t)}_{H^1(\Omega_h(t))}^2+
			\norm{h(t)}_{H_\sharp^3(0,L)}^2+
			\norm{\partial_th(t)}_{H_\sharp^1(0,L)}^2\right)\nonumber\\
			&\quad+\int_0^T\left(
			\norm{\partial_t\bu}_{L^2(\Omega_h)}^2+
			\norm{\bu}_{H^2(\Omega_h)}^2+
			\norm{p}_{H^1(\Omega_h)}^2\right)\dt\nonumber\\
			&\quad+\int_0^T\left(
			\norm{h}_{H_\sharp^{7/2}(0,L)}^2+
			\norm{\partial_th}_{H_\sharp^{3/2}(0,L)}^2+
			\norm{\partial_t^2h}_{H_\sharp^{-1/2}(0,L)}^2\right)\dt\leq C_T.\label{eq:lower-estimate}
		\end{align}
		Here $C_T$ depends only on $T,L,\rho_f,\rho_s,\mu,\alpha,\beta$, $m_0^{-1}$, and the three initial norms in \eqref{eq:data-regularity}.
	\end{theorem}
	Moreover, we establish further regularity property for the global strong solutions, which might be of interest for its own. 
	\begin{theorem}[Partial parabolic smoothing]\label{thm:smoothing}
		Let $(h,\bu,p)$ be the global strong solution furnished by Theorem~\ref{thm:global}. For every finite $T>0$, the solution satisfies
		\begin{align}
			&\mathop{\mathrm{ess\,sup}}_{0<t\leq T}t^2\left(
			\norm{\partial_t\bu(t)}_{L^2(\Omega_h(t))}^2
			+\norm{\partial_t^2h(t)}_{L_\sharp^2(0,L)}^2
			+\norm{\partial_th(t)}_{H_\sharp^2(0,L)}^2\right.\nonumber\\
			&\hspace{41mm}\left.
			+\norm{\bu(t)}_{H^2(\Omega_h(t))}^2
			+\norm{p(t)}_{H^1(\Omega_h(t))}^2
			+\norm{h(t)}_{H_\sharp^4(0,L)}^2\right)\nonumber\\
			&\qquad
			+\int_0^Tt^2
			\norm{\nabla\partial_t\bu(t)}_{L^2(\Omega_h(t))}^2
			\dt
			\leq C_T.
			\label{eq:weighted-estimate}
		\end{align}
		Moreover, for every $1\leq q<2$,
		\begin{align}
			\norm{\bu}_{L^q(0,T;W^{1,\infty}(\Omega_h))}
			\leq C_{T,q}.
			\label{eq:velocity-lipschitz}
		\end{align}
		Here $C_T$ depends only on $T,L,\rho_f,\rho_s,\mu,\alpha,\beta$, $m_0^{-1}$, and the three initial norms in \eqref{eq:data-regularity}. The constant $C_{T,q}$ additionally depends on $q$.
	\end{theorem}
	Several comments are in order.

	\begin{remark}
		Theorem \ref{thm:separation} shows that the fluid dissipation solely is in fact strong enough in such beam-fluid, to prevent possible contact. Recently, Alazard, Kukavica, and Tuffaha \cite{AlazardKukavicaTuffaha2025} showed that in two dimensions, the inviscid fluid-beam system has a global weak solution, by the Craig--Sulem--Zakharov formulation of the problem. One may also ask if the distant estimate can still hold without fluid viscosity. 
	\end{remark}

	\begin{remark}
		For Theorem \ref{thm:global}, we adopt the initial regularity of the damped-beam theorem in \cite{GrandmontHillairet2016} without adding structural viscosity. The tension by $ \beta \geq 0 $ is unnecessary because bending controls all lower structural norms on the space of periodic functions with zero mean. Section~\ref{sec:global-proof} explains the corresponding zero-tension modification of the higher continuation theorem, which was stated for positive tension in \cite{SchwarzacherSu2025}.
	\end{remark}

	\begin{remark}
		Here the additional spatial Lipschitz estimate \eqref{eq:velocity-lipschitz} is derived as a byproduct, following the argument in \cite{DanchinMucha2019}.  For further applications, it may contribute in the stability issue with low regularity.
	\end{remark}

	\subsection{Obstruction and strategy}
	The main obstacle to derive a distance estimate is due to a lack of regularity. Since higher-order estimate would require nondegeneracy of the domain ($ \min h > 0 $), one can not exploit it without a uniform distance estimate.
	The standard energy controls $h$ in $H_\sharp^2(0,L)$ and $\partial_th$ in $L_\sharp^2(0,L)$, but gives neither separation from the bottom nor a full spatial derivative of the beam velocity. This loss appears in the classical distance test as in \cite{GrandmontHillairet2016}. Indeed, for the stream function
	\begin{align*}
		\psi(t,x,y)=F(t,x)\chi\left(\frac{y}{h(t,x)}\right),\qquad \chi(z)=3z^2-2z^3,
	\end{align*}
	the solenoidal field $\bw=(-\partial_y\psi,\partial_x\psi)$ has upper trace $\partial_xF\,\be_2$. The choice $F=\partial_xh$ produces the reciprocal-height derivative through the viscous term as in \cite{GrandmontHillairet2016}, but the structural inertia gives
	\begin{align*}
		\int_0^L\partial_t^2h\,\partial_x^2h\dx
		=\partial_t\int_0^L\partial_th\,\partial_x^2h\dx
		+\norm{\partial_t\partial_xh}_{L_\sharp^2(0,L)}^2.
	\end{align*}
	The last term has an unfavorable sign for the distance estimate and cannot be bounded by the mechanical energy and fluid dissipation.

	Instead, note that the fundamental theorem of calculus in each vertical fluid column yields
	\begin{align*}
		\int_0^L\frac{|\partial_t h|^2}{h}\,\mathrm dx = \int_0^L\frac{|u_2(t,x,h(t,x))|^2}{h}\,\mathrm dx
		\leq \int_0^L \int_0^{h(t,x)} |\partial_y u_2|^2 \dy \dx
		\leq \cD.
	\end{align*}
	Related weighted column estimates appear in~\cite[Section~4.2]{GrandmontHillairet2016} and~\cite[Lemma~A.3]{Trifunovic2026}. See also \cite[Theorem 5.1]{LeoniTice2019} for the trace of functions in strip-like domains. After integration by parts in $x$, the inertial remainder for a general $F$ therefore satisfies
	\begin{align*}
		\left|\int_0^L\partial_x\partial_th\,\partial_tF\dx\right|
		\leq\sqrt{\cD}\left(\int_0^Lh|\partial_x\partial_tF|^2\dx\right)^{1/2}.
	\end{align*}
	This allows a certain degree of freedom for us to close the argument. By the preceding inequality, a higher regularity of $F$, both in space and time, is required, which is not available a priori if $ F = \partial_x h $. Motivated by the observation, we therefore seek a regularization of $F = \partial_xh$ for which the weighted norm on the right-hand side can be controlled by the fluid dissipation, with a dependence on the minimum height compatible with the distance estimate. Such a regularization must also preserve the reciprocal-height derivative generated by the fluid viscosity. To make this it explicit, we introduce the horizontal flux
	\begin{align*}
		Q(t,x)=\int_0^{h(t,x)}u_1(t,x,y)\dy,
	\end{align*}
	which satisfies $\partial_th=-\partial_xQ$, and hence
	\begin{align*}
		\partial_t\cS(t)=2\int_0^L\frac{Q\partial_xh}{h^3}\dx.
	\end{align*}
	See also \cite[(79) \& (82)]{GrandmontHillairet2016} for similar calculations. The choice $F=\partial_xh$ recovers the above derivative exactly by the stream function test procedure that generates $\partial_t \cS$. Thus, a regularized $ F $ must retain this identity as well, up to a controllable error, cf.~Lemma \ref{lem:stress-identity} below. Because of the degeneracy as $ h \to 0 $, we use a ``degenerate elliptic regularization'' of $ \partial_x h $, by solving
	\begin{align*}
		F-\ell^2\partial_x^2F=\partial_xh,\qquad \ell=\varepsilon h^{2/3},
	\end{align*}
	where $\varepsilon>0$ is fixed by the initial energy. 
	The regularization length $\ell=\varepsilon h^{2/3}$ is chosen to balance the spatial variation of the coefficients with the singular weight in the inertial estimate, i.e.,
	\begin{align*}
		|\partial_x \ell| = \frac{2}{3} \eps h^{-1/3} |\partial_x h| \leq C \eps, 
	\end{align*}
	where $ |\partial_x h| \leq C h^{1/3} $ (cf.~\eqref{eq:slope-cubic}). With this construction, we are able to particularly justify (cf. Lemma \ref{lem:time} below)
	\begin{align*}
		\int_0^Lh|\partial_x\partial_tF|^2\dx
		\leq C(\min h)^{-2/3}\cD(t),
	\end{align*}
	The resulting inertial loss is $(\min h)^{-1/3}$, which one can control by $C(1+\cS)$, cf.~Lemma~\ref{lem:geometry}. This replaces the uncontrolled spatial derivative of the beam velocity by a weighted estimate compatible with a linear Gr\"onwall argument, cf. Section \ref{sec:separation-proof}. 
	We believe that the \emph{degenerate regularized multiplier} shall be adopted to other fluid-structure interaction problems to address the no-contact/contact issues, as long as its time derivative is compatible with the weighted trace controlled by fluid dissipation, and its spatial regularization preserve the distance identity up to an error controlled by elasticity.

	The next issue is to obtain a global $H^1$-level estimate. 
	The global regularity estimate of Grandmont and Hillairet~\cite{GrandmontHillairet2016} depends strongly on the structure damping ($\gamma > 0$), while the regularity theory of Schwarzacher and Su~\cite{SchwarzacherSu2025} is built on a coupled \textit{acceleration estimate}. Testing the time-differentiated system by the accelerations preserves the hyperbolic structure of the beam and yields the estimate for the spatial gradient of the fluid time derivative, from which continuation follows whenever the height stays positive. That estimate requires initial velocity in $H^2$, initial height in $H^4$ and initial beam velocity in $H^2$, and the constants that carry the local theory depend on the inverse gap. 
	The present contribution reaches the lower regularity $H^1\times H^3\times H^1$ setting as in Grandmont and Hillairet \cite{GrandmontHillairet2016} and proves that contact never occurs. At this level the acceleration is not available as a test field at time zero, and the corresponding constant becomes unbounded in the limit. Indeed, the Eulerian temporal derivative has the boundary trace
	\begin{align*}
		\partial_t\bu\big|_{y=h}=\partial_t^2h\,\be_2-\partial_th\,\partial_y\bu\big|_{y=h},
	\end{align*}
	so it does not directly give a coupled acceleration test. Testing the beam equation by $\partial_t^2h$ also produces an elastic cross term whose time derivative leaves a negative squared norm of $\partial_t\partial_x^2h$. Thus, acceleration argument, in the form used in \cite{SchwarzacherSu2025}, cannot be run on our data. Indeed, as Schwarzacher and Su mentioned in \cite{SchwarzacherSu2025}, second-order time derivative of a solution is not a good test function for hyperbolic equations.

	We circumvent it by tangential estimates and a negative half order accelerate estimate, which then control the final fluid acceleration and Stokes regularity via a solenoidal lifting. 
	On the fixed strip $\Omega_1$, the Piola velocity $\bv=B_h^\top(\bu\circ\chi_h)$ is solenoidal and has upper trace $\partial_th\,\be_2$, cf.~\eqref{eq:piola-velocity} below. Essentially tangential derivatives preserve both constraints. The coupled test $(-\partial_x^2\bv,-\partial_t\partial_x^2h)$ controls the horizontal derivatives of the fluid and the lower structural energy, while the fluid dissipation gives $\partial_th\in L^2(0,T;H_\sharp^{3/2}(0,L))$ through the upper trace. Combining with a subsequent solenoidal lifting test with upper trace $(1-\partial_x^2)^{3/2}(h-H)\be_2$, we are able to derive $h\in L^2(0,T;H_\sharp^{7/2}(0,L))$, cf.~Lemma \ref{lem:lower-height} below.
	Then formally by comparison in \eqref{eq:beam}, the beam acceleration is expected to stay in a negative half-order Sobolev space. This is further established with an admissible pair $((N^2-\partial_x^2)^{-1/2}\partial_t\bv,(N^2-\partial_x^2)^{-1/2}\partial_t^2h)$, where negative-order tangential multiplier is employed. The multiplier with $N$ that is chosen to be sufficiently large here filters the singular part of the viscous commutator, whose coefficient in the fluid $H^2$ norm is $N^{-2}$. The resulting estimate for $ \partial_t^2 h $ lies in $ L^2(0,T;H_\sharp^{-1/2}(0,L)) $, supplying the remaining boundary norm in the fluid estimate, \textit{without} requiring any initial acceleration, cf.~Lemma \ref{lem:lower-acceleration}.
	Note that subtracting a stationary solenoidal Stokes lift of the boundary velocity $\partial_th\,\be_2$ reduces the fluid equation to homogeneous boundary data. The time derivative of this lift is controlled in $L^2(0,T;L^2(\Omega_1))$ by $\norm{\partial_t^2h}_{L^2(0,T;H_\sharp^{-1/2}(0,L))}$. This gives a nonstationary fluid estimate on the entire chosen interval, which combined the tangential estimates above closes the argument by Gr\"onwall's inequality.

	Additionally, we would like to explore the regularity property for the global strong solutions. In particular, we aim to figure out what does the fluid dissipation provide in such a parabolic-hyperbolic coupled system. This motivates us to derive the \textit{time-weighted estimate}, cf. \eqref{eq:weighted-estimate} above. Following the scheme of Danchin and Mucha~\cite{DanchinMucha2019} (see also \cite{Li2017}), we carry out the time-weighted estimates on our fluid-structure interaction problem under the energy estimate, uniform separation, and $ H^1 $-estimate. The quadratic weight is then obtained by averaging the higher propagation estimate over positive starting times. Precisely the propagation estimate presupposes the higher norms at its starting time and therefore cannot be restarted at $t=0$ on our data, so the estimate holds for positive times only and controls the initial layer rather than supplying a new existence mechanism.

	Note that the \textit{time-weighted estimate} records the \textit{partial parabolic smoothing} of the coupled fluid-structure system (parabolic--hyperbolic coupling). The smoothing originates in the viscous fluid alone, since no structural damping is present and the beam equation is hyperbolic. The elastic beam gains regularity only through the coupling, which transmits the fluid regularity to the structure across the moving interface. 
	Nevertheless, the estimate is of independent interest in this form, since it quantifies a smoothing mechanism that is available to coupled parabolic--hyperbolic problems at low initial regularity, which is not visible in an unweighted estimate. Thus, we expect similar time-weighted estimates to be applicable to broader situations of fluid--structure interactions.

	\subsection{Outline}
	In Section~\ref{sec:separation}, the quantitative separation estimate is justified, including admissibility of the distance test in the lower regularity class. Section~\ref{sec:lower-estimates} establishes the direct global lower-order estimates, which is supplied by delicate tangential estimates for height, velocity and acceleration. In Section~\ref{sec:global-proof}, the global solution is constructed via higher-regularity approximation, and uniqueness is shown as well. Section~\ref{sec:time-weighted-estimates} then derives the higher regularity estimates with quadratic time weights.

	\section{Quantitative Separation}\label{sec:separation}
	In this section, we prove Theorem \ref{thm:separation}, which establishes the quantitative distance estimate. Before introducing the main argument, let us briefly justify the energy-dissipation law of \eqref{eq:model}, which is the basis of further estimates. Throughout this section, $C$ denotes a positive constant depending only on $\cE(0),H,L,\rho_f,\rho_s,\mu,\alpha,\beta$; its value may change between occurrences. These constants are independent of the minimum height. 
	\begin{lemma}\label{lem:mechanical-energy}
		Every solution in Definition~\ref{def:strong} conserves the mean height and satisfies \eqref{eq:energy-identity}.
	\end{lemma}
	\begin{proof}
		Integrating incompressibility and using the prescribed traces, we obtain $\int_0^L\partial_th\dx=0$. On a compact positive-gap interval, the two-dimensional product estimate ensures $\bu\cdot\nabla\bu\in L^2(0,T;L^2(\Omega_h))$. Then we use the test pair $(\bu, \partial_t h \be_2)$ for the coupled problem. Reynolds transport contributes $\frac12\int_0^L|\partial_th|^2\partial_th\dx$, which cancels the convective boundary flux. The beam equation can be paired with $\partial_th\in L^\infty(0,T;H_\sharp^1(0,L))$. The elastic product rule follows from $\partial_x^2h\in L^2(0,T;H_\sharp^1(0,L))$ and $\partial_t\partial_x^2h\in L^2(0,T;H_\sharp^{-1}(0,L))$. Fluid traction and beam work cancel because the traces match. We thus obtain the energy identity with dissipation $2\mu\int_{\Omega_h}|D\bu|^2\dA$. The cross-gradient integration by parts proved in Lemma~\ref{lem:stress-identity} identifies this dissipation with $\mu\int_{\Omega_h}|\nabla\bu|^2\dA$. Temporal regularization and the continuous initial traces justify the calculation from zero.
	\end{proof}

	\subsection{Geometry and estimates from the fluid dissipation}
	By \eqref{eq:energy-identity}, we know
	\begin{align}
		\norm{\partial_x^2 h (t)}_{L_\sharp^2(0,L)}\leq\sqrt{\frac{2\cE(0)}\alpha},\qquad
		0<h(t,x)\leq H+L^{3/2}\sqrt{\frac{2\cE(0)}\alpha}.\label{eq:energy-geometry}
	\end{align}
	Indeed, since $\partial_x h$ has zero mean, we have $\norm{\partial_x h}_{L_\sharp^\infty(0,L)}\leq\sqrt L\norm{\partial_x^2 h}_{L_\sharp^2(0,L)}$, and the oscillation of $h$ is at most $L\norm{\partial_x h}_{L_\sharp^\infty(0,L)}$. 

	We first establish a Glaeser-type estimate for the slope and a quantitative reciprocal-height estimate for the minimum. The former controls the spatial variation of height uniformly as the gap decreases (see also \cite[Proposition 6]{GrandmontHillairet2016} and \cite[Lemma A.1]{BKLM2026}), while the latter converts a bound on the reciprocal-height integral into a positive lower bound for the gap. 
	\begin{lemma}
		\label{lem:geometry}
		Every positive periodic $h\in H_\sharp^2(0,L)$ satisfies
		\begin{align}
			| \partial_x h (x)|^3&\leq\frac{9}{4}\norm{\partial_x^2 h}_{L_\sharp^2(0,L)}^2h(x).\label{eq:slope-cubic}
		\end{align}
		Moreover, it holds
		\begin{align}
			(\min h)^{-1}\leq\frac{2}L \int_0^L \frac1h\dx+\frac{1}{3}\norm{\partial_x^2 h}_{L_\sharp^2(0,L)}^2 \left(\int_0^L \frac1h\dx\right)^3,
			\label{eq:min-entropy0}
		\end{align}
		In particular,
		\begin{align}
			(\min h)^{-1/3}\leq C\left(1+\int_0^L \frac1h\dx\right).
			\label{eq:min-entropy}
		\end{align}
	\end{lemma}
	\begin{proof}
		The one-dimensional Sobolev embedding and positivity of $h$ justify the chain rules and integrations by parts below. We first observe that
		\begin{align*}
			\partial_x\left(\frac{(\partial_x h)^3}{h}\right)
			=3\frac{(\partial_x h)^2}{h}\partial_x^2h
			-\frac{(\partial_x h)^4}{h^2}
			=\frac94|\partial_x^2h|^2
			-\left(\frac{(\partial_x h)^2}{h}
			-\frac32\partial_x^2h\right)^2
			\leq\frac94|\partial_x^2h|^2.
		\end{align*}
		Since $\partial_x h$ has zero mean and is continuous, it vanishes somewhere in each period. Integrating the preceding inequality from such a zero to $x$ bounds $(\partial_x h(x))^3/h(x)$ from above. Integrating from $x$ to the next periodic copy of the same zero bounds it from below. Consequently,
		\begin{align*}
			\frac{|\partial_x h(x)|^3}{h(x)}
			\leq\frac94\int_0^L|\partial_x^2h|^2\dx,
		\end{align*}
		which implies \eqref{eq:slope-cubic}.

		For the reciprocal-height estimate, we apply periodic integration by parts and the Cauchy--Schwarz inequality to obtain
		\begin{align*}
			\int_0^L\frac{|\partial_x h|^2}{h^3}\dx
			=\frac12\int_0^L\frac{\partial_x^2h}{h^2}\dx
			& \leq\frac12
			\left(\int_0^L|\partial_x^2h|^2\dx\right)^{1/2}
			\left(\int_0^L\frac1{h^4}\dx\right)^{1/2} \\
			& \leq\frac{\norm{\partial_x^2 h}_{L_\sharp^2(0,L)}}{2} \left(\int_0^L \frac1h\dx\right)^{1/2} (\min h)^{-3/2}.
		\end{align*}
		The periodic $W^{1,1}$ estimate bounds the maximum of $h^{-1}$ by its mean plus one half of the $L^1$ norm of its derivative. Indeed, periodicity implies that its total variation is at least twice its oscillation. Applying this estimate and then the Cauchy--Schwarz and Young inequalities, we obtain
		\begin{align*}
			(\min h)^{-1}
			&\leq\frac 1L \int_0^L \frac1h\dx+\frac12\int_0^L
			\frac{|\partial_x h|}{h^2}\dx\\
			&\leq\frac 1L\int_0^L \frac1h\dx+\frac12
			\left(\int_0^L\frac{|\partial_x h|^2}{h^3}\dx\right)^{1/2}
			\left(\int_0^L\frac1h\dx\right)^{1/2}\\
			&\leq\frac 1L\int_0^L \frac1h\dx
			+ \frac1{2} (\min h)^{-1}
			+ \frac{\norm{\partial_x^2 h}_{L_\sharp^2(0,L)}^2}{6} \left(\int_0^L \frac1h\dx\right)^3,
		\end{align*}
		which shows \eqref{eq:min-entropy0}. Taking cube roots, using $(a+b)^{1/3}\leq a^{1/3}+b^{1/3}$ for $a,b\geq0$, and recalling $\norm{\partial_x^2h}_{L_\sharp^2(0,L)}^2\leq2\cE(0)/\alpha$, we obtain
		\begin{align*}
			(\min h)^{-1/3}
			&\leq\left(\frac2L\right)^{1/3}\left(\int_0^L\frac1h\dx\right)^{1/3}
			+\left(\frac{2\cE(0)}{3\alpha}\right)^{1/3}\int_0^L\frac1h\dx
			\leq C\left(1+\int_0^L\frac1h\dx\right),
		\end{align*}
		which proves \eqref{eq:min-entropy}.
	\end{proof}

	For the rest of this section, $h$ satisfies the energy bounds in \eqref{eq:energy-geometry}. Fix the following parameters:
	\begin{align}
		\varepsilon=\frac{3}{32\left(1+\left(\frac{9\cE(0)}{2\alpha}\right)^{1/3}\right)},\qquad
		\ell=\varepsilon h^{2/3}.
	\end{align}
	Then it follows from Lemma~\ref{lem:geometry} that
	\begin{align}
		|\partial_x h|\leq\left(\frac{9\cE(0)}{2\alpha}\right)^{1/3}h^{1/3},\qquad
		\norm{\partial_x\ell}_{L_\sharp^\infty(0,L)}\leq\frac1{16}.\label{eq:length-lipschitz}
	\end{align}

	The horizontal flux links the beam motion to the fluid dissipation. More precisely, incompressibility implies $\partial_t h=-\partial_xQ$, so the derivative of the reciprocal-height integral can be expressed in terms of $Q$. The no-slip condition at both ends of each vertical column controls $Q$ with weight $h^{-3}$, which is precisely the weight in the viscous distance identity.

	\begin{lemma}
		\label{lem:flux}
		Define the horizontal flux by
		\begin{align*}
			Q(t,x)=\int_0^{h(t,x)}u_1(t,x,y)\dy.
		\end{align*}
		Then
		\begin{align}
			\partial_t h =- \partial_x Q,\qquad
			12\int_0^L\frac{Q^2}{h^3}\dx\leq\cD,\qquad
			\int_0^L\frac{(\partial_t h)^2}{h}\dx\leq\cD.\label{eq:flux-estimates}
		\end{align}
		Moreover,
		\begin{align}
			\norm{\bu(x,\cdot)}_{L^2(0,h(x))}
			\leq h(x)\norm{\partial_y\bu(x,\cdot)}_{L^2(0,h(x))}.\label{eq:column-poincare}
		\end{align}
	\end{lemma}

	\begin{proof}
		Differentiating $Q$ and using $u_1(x,h)=0$, we find
		\begin{align*}
			\partial_x Q =\int_0^h \partial_x u_1 \dy=-\int_0^h \partial_y u_2 \dy=- \partial_t h.
		\end{align*}
		The two zero endpoint values of $u_1$ imply
		\begin{align*}
			Q=-\int_0^h\left(y-\frac h2\right) \partial_y u_1 \dy,
			\qquad |Q|^2\leq\frac{h^3}{12}\int_0^h| \partial_y u_1 |^2\dy.
		\end{align*}
		Also $\partial_t h =\int_0^h \partial_y u_2 \dy$, so $(\partial_t h)^2\leq h\int_0^h| \partial_y u_2 |^2\dy$. Integration in $x$ proves \eqref{eq:flux-estimates}. Finally, \eqref{eq:column-poincare} follows from the bottom condition $\bu(x,0)=0$ and the fundamental theorem of calculus.
	\end{proof}
	\begin{remark}
		The powers $h^{-3}$ and $h^{-1}$ in \eqref{eq:flux-estimates} follow from the squared $L^2(0,h)$ norms of $y-h/2$ and $1$, respectively. Thus fluid dissipation controls the flux and the beam velocity with the height weights needed to close the coupled distance identity. Although these estimates are derived while $h>0$, their constants are independent of $\min h$. The weighted trace estimate underlying the last inequality in \eqref{eq:flux-estimates}, together with a weighted column estimate, also appears in \cite[Lemma~A.3]{Trifunovic2026}.
	\end{remark}

	\subsection{The regularized multiplier}

	For each positive height $h$, let $F$ be the periodic solution of
	\begin{align}
		F-\ell^2\partial_x^2F=\partial_xh, \label{eq:elliptic}
	\end{align}
	where $\ell=\varepsilon h^{2/3}$ is the local smoothing length for $\partial_xh$. The exponent $2/3$ is consistent with both the slope estimate, which bounds $\partial_x\ell$ uniformly, and the height-weighted time-derivative estimates below, which produce a loss of at most $(\min h)^{-1/3}$ in the structural inertial term. Lemma~\ref{lem:geometry} bounds this loss by $C(1+\cS)$.
	After division by $\ell^2$, equation~\eqref{eq:elliptic} reads $- \partial_x^2 F +\ell^{-2}F=\ell^{-2} \partial_x h$. For a fixed positive $h$, the bilinear form
	\begin{align*}
		(F,\varphi)\mapsto\int_0^L \partial_x F \partial_x \varphi \dx+\int_0^L \ell^{-2}F\varphi\dx
	\end{align*}
	is coercive on $H_\sharp^1(0,L)$. The Lax--Milgram theorem and one-dimensional elliptic regularity therefore ensure a unique solution. This construction may depend on the positive minimum of the fixed height, while the following estimates have constants uniform as that minimum decreases. 

	\begin{lemma}[Pointwise bounds]
		The solution of \eqref{eq:elliptic} satisfies
		\begin{align}
			|F|\leq Ch^{1/3},\qquad
			| \partial_x F |\leq Ch^{-1/3},\qquad
			| \partial_x^2 F |\leq Ch^{-1},\label{eq:pointwise}
		\end{align}
		where $C > 0$ does not depend on $\min h$.
	\end{lemma}
	\begin{proof}
		Since $h\in H_\sharp^2(0,L)$ is positive, \eqref{eq:elliptic} implies $F\in H_\sharp^3(0,L)\hookrightarrow C^2([0,L])$. We estimate $F$ and $\ell\partial_xF$ simultaneously, using
		\begin{align*}
			|F|+\ell|\partial_xF|
			=\max\bigl\{|F+\ell\partial_xF|,\,
			|F-\ell\partial_xF|\bigr\}.
		\end{align*}
		The combinations on the right satisfy first-order identities involving only $\partial_xh$ and $\partial_x\ell$. Indeed, since
		\begin{align*}
			\ell^2\partial_x^2F=F-\partial_xh,
			\qquad
			\ell\partial_x(h^{-1/3})
			=-\frac12(\partial_x\ell)h^{-1/3},
		\end{align*}
		direct differentiation yields
		\begin{align*}
			\ell\partial_x\left(
			\frac{F\pm\ell\partial_xF}{h^{1/3}}\right)
			&=
			\pm\frac{F\pm\ell\partial_xF}{h^{1/3}}
			-\frac{\partial_x\ell}{2}
			\frac{F\mp\ell\partial_xF}{h^{1/3}}
			\mp\frac{\partial_xh}{h^{1/3}}.
		\end{align*}

		Choose the sign for which the absolute maximum of these two periodic functions is larger, and take a point where this maximum is attained. The derivative of the selected function vanishes there, while the absolute value of the other function is no larger. Taking absolute values in the preceding identity and using \eqref{eq:length-lipschitz}, we obtain
		\begin{align*}
			\max_{\pm}
			\left\|\frac{F\pm\ell\partial_xF}{h^{1/3}}\right\|
			_{L_\sharp^\infty(0,L)}
			&\leq \frac1{32}\max_{\pm}
			\left\|\frac{F\pm\ell\partial_xF}{h^{1/3}}\right\|
			_{L_\sharp^\infty(0,L)}
			+\left\|\frac{\partial_xh}{h^{1/3}}\right\|
			_{L_\sharp^\infty(0,L)}.
		\end{align*}
		Absorbing the first term and recalling the slope bound in \eqref{eq:length-lipschitz}, we conclude that, at every point,
		\begin{align*}
			\frac{|F|+\ell|\partial_xF|}{h^{1/3}}
			&\leq \frac{32}{31}
			\norm{\frac{\partial_xh}{h^{1/3}}}
			_{L_\sharp^\infty(0,L)}
			\leq C.
		\end{align*}
		Consequently, since $\ell=\varepsilon h^{2/3}$,
		\begin{align*}
			|F|\leq Ch^{1/3},
			\qquad
			|\partial_xF|\leq C\varepsilon^{-1}h^{-1/3}.
		\end{align*}
		Finally, the equation itself implies
		\begin{align*}
			|\partial_x^2F|
			\leq \ell^{-2}\bigl(|F|+|\partial_xh|\bigr)
			\leq C\varepsilon^{-2}h^{-1}.
		\end{align*}
		This completes the proof.
	\end{proof}

	The next identity provides the positive term that will absorb the defect in the viscous distance calculation.
	\begin{lemma}\label{lem:elastic}
		For a positive $h\in H_\sharp^3(0,L)$, it holds
		\begin{align}
			\beta& \int_0^L \partial_x^2 h \partial_x F \dx+\alpha\int_0^L \partial_x^3 h \partial_x^2 F \dx \nonumber\\
			& \geq\frac{15\alpha}{16}
			\bigl(\norm{\partial_x^2 F}_{L_\sharp^2(0,L)}^2+\norm{\ell \partial_x^3 F}_{L_\sharp^2(0,L)}^2\bigr)
			+\beta\bigl(\norm{\partial_x F}_{L_\sharp^2(0,L)}^2+\norm{\ell \partial_x^2 F}_{L_\sharp^2(0,L)}^2\bigr)\geq0.
			\label{eq:elastic-coercivity}
		\end{align}
	\end{lemma}

	\begin{proof}
		By \eqref{eq:elliptic}, we have 
		\begin{align*}
			\partial_x^2 h = \partial_x F -\partial_x(\ell^2 \partial_x^2 F),\qquad
			\partial_x^3 h = \partial_x^2 F -\partial_x^2(\ell^2 \partial_x^2 F).
		\end{align*}
		Then $F\in H_\sharp^4(0,L)$ because $h\in H_\sharp^3(0,L)$. Integration by parts yields
		\begin{align*}
			\int_0^L \partial_x^2 h \partial_x F \dx
			&=\norm{\partial_x F}_{L_\sharp^2(0,L)}^2+\norm{\ell \partial_x^2 F}_{L_\sharp^2(0,L)}^2,\\
			\int_0^L \partial_x^3 h \partial_x^2 F \dx
			&=\norm{\partial_x^2 F}_{L_\sharp^2(0,L)}^2+\norm{\ell \partial_x^3 F}_{L_\sharp^2(0,L)}^2
			+\int_0^L \partial_x(\ell^2) \partial_x^2 F \partial_x^3 F.
		\end{align*}
		Moreover, 
		\begin{align*}
			\left|\int_0^L \partial_x(\ell^2) \partial_x^2 F \partial_x^3 F \dx\right|
			\leq\frac18\norm{\partial_x^2 F}_{L_\sharp^2(0,L)}\norm{\ell \partial_x^3 F}_{L_\sharp^2(0,L)}
			\leq\frac1{16}\bigl(\norm{\partial_x^2 F}_{L_\sharp^2(0,L)}^2+\norm{\ell \partial_x^3 F}_{L_\sharp^2(0,L)}^2\bigr).
		\end{align*}
		Adding them together with $\alpha > 0,\beta \geq 0$ proves \eqref{eq:elastic-coercivity}.
	\end{proof}

	Now we turn to the temporal regularity. Taking the time derivative of \eqref{eq:elliptic} leads to
	\begin{align}
		\partial_t F -\ell^2 \partial_x^2\partial_t F = \partial_x\partial_t h +\frac43\frac{F-\partial_x h}{h}\partial_t h,\label{eq:time-resolvent}
	\end{align}
	where $\left|\frac43\frac{F-\partial_x h}{h}\right|\leq Ch^{-2/3}$.
	\begin{lemma}
		\label{lem:time}
		For a strong solution, it follows
		\begin{gather}
			\int_0^L h(\partial_t F)^2\dx\leq C\cD,\qquad
			\int_0^L h(\partial_x\partial_t F)^2\dx\leq C (\min h)^{-2/3}\cD,\label{eq:time-dissipation}\\
			\left|\int_0^L \partial_x\partial_t h \partial_t F \dx\right|\leq C(1+\cS)\cD.
		\end{gather}
	\end{lemma}

	\begin{proof}
		Testing \eqref{eq:time-resolvent} by $h \partial_t F$ and integrating by parts, we obtain the exact identity
		\begin{align}
			&\int_0^L h(\partial_t F)^2\dx+\int_0^L \ell^2 h(\partial_x\partial_t F)^2\dx
			\nonumber\\
			&\quad=-\int_0^L\partial_x(\ell^2 h)\,\partial_t F\,\partial_x\partial_t F\dx-\int_0^L h\,\partial_t h\,\partial_x\partial_t F\dx
			+\int_0^L\left(\frac43F-\frac73\partial_x h\right)\partial_t h\,\partial_t F\dx.
			\label{eq:first-weighted-identity}
		\end{align}
		Since $\partial_x(\ell^2 h) = \frac72 \partial_x \ell h \ell$, we have 
		\begin{align*}
			\left|\int_0^L\partial_x(\ell^2 h) \partial_t F \partial_x\partial_t F \dx\right|
			\leq\frac7{64}\left(\int_0^L h(\partial_t F)^2\dx+\int_0^L \ell^2 h(\partial_x\partial_t F)^2\dx\right),
		\end{align*}
		where we used $\|\partial_x\ell\|_{L_\sharp^\infty(0,L)} \leq 1/16$.
		Moreover, by Young's inequality, $\ell = \eps h^{2/3}$, \eqref{eq:slope-cubic}, and \eqref{eq:pointwise} one records
		\begin{align*}
			\left|\int_0^L h \partial_t h \partial_x\partial_t F \dx\right|
			&\leq\frac14\int_0^L \ell^2 h(\partial_x\partial_t F)^2\dx+C\int_0^L h^{-1/3}(\partial_t h)^2\dx,\\
			\left|\int_0^L\left(\frac43F-\frac73 \partial_x h \right) \partial_t h \partial_t F \dx\right|
			&\leq\frac14\int_0^L h(\partial_t F)^2\dx+C\int_0^L h^{-1/3}(\partial_t h)^2\dx.
		\end{align*}
		Therefore, by \eqref{eq:energy-geometry} and \eqref{eq:flux-estimates}, we infer from \eqref{eq:first-weighted-identity} that
		\begin{align*}
			\int_0^L h(\partial_t F)^2\dx+\int_0^L \ell^2h(\partial_x\partial_t F)^2\dx
			\leq C\int_0^L h^{-1/3}(\partial_t h)^2\dx
			\leq C\int_0^L h^{-1}(\partial_t h)^2\dx
			\leq C\cD,
		\end{align*}
		which proves the first inequality of \eqref{eq:time-dissipation}.

		Now testing instead by $(h/\ell^2) \partial_t F$, one has
		\begin{align}
			&\int_0^L\frac{h}{\ell^2}(\partial_t F)^2\dx+\int_0^L h(\partial_x\partial_t F)^2\dx
			\nonumber\\
			&\qquad=
			-\int_0^L\partial_x h\,\partial_t F\,\partial_x\partial_t F\dx
			-\int_0^L\frac{h}{\ell^2}\,\partial_t h\,\partial_x\partial_t F\dx
			+\int_0^L\frac{\frac43F-\partial_x h}{\ell^2}\,\partial_t h\,\partial_t F\dx.
			\label{eq:second-weighted-identity}
		\end{align}
		Here $h/\ell^2=\varepsilon^{-2}h^{-1/3}$ and $\ell \partial_x h /h=\frac32 \partial_x \ell$ and $\|\partial_x\ell\|_{L^\infty}\leq 1/16$. Thus the first term on the right-hand side is controlled by
		\begin{align*}
			\left|\int_0^L
			(\partial_x h)(\partial_t F)(\partial_x\partial_t F)\dx\right|
			&\leq
			\frac32\|\partial_x\ell\|_{L^\infty}
			\int_0^L\left|\frac{\sqrt h}{\ell}\,\partial_t F\right|\left|\sqrt h\,\partial_x\partial_t F\right|\dx
			\\
			&\quad\leq
			\frac{3}{64}
			\int_0^L\left(\frac{h}{\ell^2}|\partial_t F|^2+h|\partial_x\partial_t F|^2\right)\dx.
		\end{align*}
